import { useEffect, useRef, useState } from "react";
import { supabase } from "../../lib/supabase";
import { Send, Loader2 } from "lucide-react";
import { toast } from "sonner";
import AvatarFrame, { getFrameEffects, getRankTitle } from "../AvatarFrame";

interface Message {
  id: string;
  club_id: string;
  user_id: string;
  message: string;
  message_type: 'text' | 'system';
  created_at: string;
  profiles?: {
    nickname: string;
    avatar_url: string | null;
    level: number;
  };
}

export default function ClubChat({ clubId, userId }: { clubId: string; userId: string }) {
  const [messages, setMessages] = useState<Message[]>([]);
  const [text, setText] = useState("");
  const [sending, setSending] = useState(false);

  const bottomRef = useRef<HTMLDivElement>(null);

  const scrollBottom = () => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const fetchMessages = async () => {
    if (!clubId || clubId === 'undefined') return;

    const { data, error } = await supabase
      .from("club_messages")
      .select(`*, profiles:public_profiles!club_messages_user_public_profile_fkey (nickname, avatar_url, level)`)
      .eq("club_id", clubId)
      .order("created_at", { ascending: true })
      .limit(100); // Nên có limit để tránh tràn RAM

    if (!error && data) {
      setMessages(data);
      setTimeout(scrollBottom, 100);
    }
  };

  // HÀM TỐI ƯU REALTIME: Chỉ fetch tin mới nhất
  const fetchNewMessage = async (msgId: string) => {
    const { data } = await supabase
      .from("club_messages")
      .select(`*, profiles:public_profiles!club_messages_user_public_profile_fkey (nickname, avatar_url, level)`)
      .eq("id", msgId)
      .single();
      
    if (data) {
      setMessages((prev) => [...prev, data]);
      setTimeout(scrollBottom, 100);
    }
  };

  useEffect(() => {
    // eslint-disable-next-line react-hooks/exhaustive-deps
    fetchMessages();

    const channel = supabase
      .channel(`club-chat-${clubId}`)
      .on("postgres_changes", {
          event: "INSERT",
          schema: "public",
          table: "club_messages",
          filter: `club_id=eq.${clubId}`,
        },
        (payload: { new: { id: string } }) => {
          // GỌI HÀM NÀY THAY VÌ FETCH TOÀN BỘ
          fetchNewMessage(payload.new.id);
        }
      )
      .subscribe();

    return () => { supabase.removeChannel(channel); };
  }, [clubId]);

  const sendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault(); // CHẶN LOAD TRANG KHI BẤM ENTER
    if (!text.trim()) return;

    setSending(true);
    
    // Lưu lại text lỡ lỗi còn khôi phục được
    const tempText = text.trim();
    setText(""); 

    const { error } = await supabase.from("club_messages").insert({
      club_id: clubId,
      user_id: userId,
      message: tempText,
      message_type: 'text' // Mặc định là text
    });

    if (error) {
      toast.error("Không gửi được tin nhắn");
      setText(tempText); // Trả lại text cho user
    }

    setSending(false);
  };

  return (
    <div className="flex flex-col h-full">
      {/* message list */}
      <div className="flex-1 overflow-y-auto space-y-4 p-4">
        {messages.map((msg) => {
          const mine = msg.user_id === userId;

          // RENDER TIN NHẮN HỆ THỐNG
          if (msg.message_type === 'system') {
            return (
              <div key={msg.id} className="flex justify-center my-2">
                <span className="bg-white/10 text-slate-400 text-[10px] uppercase tracking-widest px-4 py-1.5 rounded-full font-bold">
                  {msg.message}
                </span>
              </div>
            );
          }

          // RENDER TIN NHẮN BÌNH THƯỜNG
          return (
            <div key={msg.id} className={`flex items-end gap-3 ${mine ? "justify-end" : "justify-start"}`}>
              {!mine && (
                <div className="flex-shrink-0">
                  <AvatarFrame 
                    level={msg.profiles?.level || 1}
                    avatarUrl={msg.profiles?.avatar_url || null}
                    size="sm"
                    showBadge={false}
                  />
                </div>
              )}
              <div className={`max-w-[70%] rounded-2xl px-4 py-3 shadow-md ${
                  mine ? "bg-cyan-500 text-black rounded-tr-sm" : "bg-slate-800 text-white rounded-tl-sm border border-white/5"
                }`}
              >
                {!mine && (
                  <div className="flex items-center gap-2 mb-1">
                    <p className="text-[11px] text-cyan-400 font-black">
                      {msg.profiles?.nickname || "Đồng đạo"}
                    </p>
                    <span className={`text-[9px] font-bold uppercase ${getFrameEffects(msg.profiles?.level || 1).textColor}`}>
                      {getRankTitle(msg.profiles?.level || 1)}
                    </span>
                  </div>
                )}
                <p className="text-sm leading-relaxed">{msg.message}</p>
              </div>
            </div>
          );
        })}
        <div ref={bottomRef} />
      </div>

      {/* input - ĐỔI THÀNH FORM ĐỂ BẮT SỰ KIỆN ENTER */}
      <form onSubmit={sendMessage} className="border-t border-slate-800 p-3 flex gap-2 bg-slate-900/50">
        <input
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Nhắn gì đó cho bang hội..."
          className="flex-1 bg-slate-800 border border-white/5 text-white rounded-xl px-4 py-3 outline-none focus:border-cyan-500/50 transition-colors"
        />

        <button
          type="submit"
          disabled={sending || !text.trim()} // Rỗng thì mờ nút luôn
          className="w-12 h-12 rounded-xl bg-cyan-500 flex items-center justify-center text-black active:scale-95 transition-transform disabled:opacity-50"
        >
          {sending ? <Loader2 className="animate-spin" size={18} /> : <Send size={18} />}
        </button>
      </form>
    </div>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { supabase } from "../../lib/supabase";
import { AnimatePresence, motion } from "framer-motion";
import {
  Trophy,
  Flame,
  Droplets,
  Crown,
  Medal,
  Loader2,
  ChevronLeft,
  MessageSquare,
  LayoutDashboard,
  ShieldAlert,
  MoreVertical,
  Shield,
  User,
  XCircle,
  History,
  Edit2,
  X,
  AlertTriangle
} from "lucide-react";
import { toast } from "sonner";
import ClubChat from "./ClubChat"; // Cực kỳ quan trọng: Nhớ import file Chat vào đây sếp nhé!

interface Club {
  id: string;
  name: string;
  description?: string;
  weekly_goal_ml?: number;
  owner_id: string;
  min_level_required: number;
}

interface Leader {
  user_id: string;
  total_ml: number;
  role: string;
  profiles?: {
    nickname?: string;
    avatar_url?: string;
  };
}

interface Activity {
  id: string;
  message: string;
  amount: number;
  created_at: string;
  profiles?: {
    nickname?: string;
  };
}

interface AdminLog {
  id: string;
  created_at: string;
  action: string;
}

export default function ClubDashboard({
  clubId,
  userId, // THÊM PROP NÀY ĐỂ TRUYỀN CHO CHAT
  onBack,
}: {
  clubId: string;
  userId: string; // THÊM PROP NÀY
  onBack: () => void;
}) {
  const [club, setClub] = useState<Club | null>(null);
  const [leaders, setLeaders] = useState<Leader[]>([]);
  const [activities, setActivities] = useState<Activity[]>([]);
  const [loading, setLoading] = useState(true);
  const [isDisbanding, setIsDisbanding] = useState(false);
  const [managingMember, setManagingMember] = useState<Leader | null>(null);
  const [adminLogs, setAdminLogs] = useState<AdminLog[]>([]);
  const [clubLevel, setClubLevel] = useState(1);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingClubMinLevel, setEditingClubMinLevel] = useState(1);
  const [editingClubName, setEditingClubName] = useState("");
  const [editingClubDesc, setEditingClubDesc] = useState("");
  const [isUpdating, setIsUpdating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  
  // STATE CHUYỂN TAB
  const [tab, setTab] = useState<'overview' | 'chat' | 'admin'>('overview');

  const currentUserRole = useMemo(() => {
    return leaders.find(l => l.user_id === userId)?.role;
  }, [leaders, userId]);

  const isAdmin = currentUserRole === 'owner' || currentUserRole === 'deputy';

  const goal = club?.weekly_goal_ml || 100000;

  const totalMl = useMemo(() => {
    return leaders.reduce((sum, item) => sum + item.total_ml, 0);
  }, [leaders]);

  const progress = Math.min((totalMl / goal) * 100, 100);

  const fetchDashboard = async () => {
    setLoading(true);
    setError(null);
    try {
      // Sử dụng Promise.allSettled để tất cả các API đều chạy, kể cả khi một trong số chúng lỗi
      const results = await Promise.allSettled([
        supabase.from("clubs").select("id,name,description,weekly_goal_ml,owner_id,min_level_required").eq("id", clubId).maybeSingle(),
        supabase.from('club_members').select('user_id, role, total_ml, profiles:public_profiles!club_members_user_public_profile_fkey(nickname, avatar_url)').eq('club_id', clubId).order('total_ml', { ascending: false }).limit(50),
        supabase.from("club_activity").select(`id, message, amount, created_at, profiles:public_profiles!club_activity_user_public_profile_fkey (nickname)`).eq("club_id", clubId).order("created_at", { ascending: false }).limit(20),
        supabase.from('club_admin_logs').select(`id, created_at, action`).eq('club_id', clubId).order('created_at', { ascending: false }).limit(50),
        supabase.rpc('get_club_level', { p_club_id: clubId })
      ]);

      // Xử lý từng kết quả một cách an toàn
      if (results[0].status === 'fulfilled' && results[0].value.data) {
        setClub(results[0].value.data);
      } else {
        if (results[0].status === 'rejected') {
          console.error("Error fetching club info:", results[0].reason);
        }
        // Throw a user-friendly error if club is not found or access is denied
        throw new Error("Không thể tải thông tin bang hội. Có thể bang hội không tồn tại hoặc bạn không có quyền truy cập.");
      }

      if (results[1].status === 'fulfilled' && results[1].value.data) {
        setLeaders(results[1].value.data as Leader[]);
      } else {
        console.error("Error fetching leaders:", results[1].status === 'rejected' && results[1].reason);
        setLeaders([]); // Fallback
      }

      if (results[2].status === 'fulfilled' && results[2].value.data) {
        setActivities(results[2].value.data as Activity[] || []);
      } else {
        console.error("Error fetching activities:", results[2].status === 'rejected' && results[2].reason);
        setActivities([]); // Fallback
      }

      if (results[3].status === 'fulfilled' && results[3].value.data) {
        setAdminLogs(results[3].value.data as AdminLog[]);
      } else {
        console.warn("Could not fetch admin logs. The table might not exist yet.", results[3].status === 'rejected' && results[3].reason);
        setAdminLogs([]); // Fallback
      }

      if (results[4].status === 'fulfilled' && results[4].value.data) {
        setClubLevel(results[4].value.data);
      } else {
        console.warn("Could not fetch club level. The RPC might not exist yet.", results[4].status === 'rejected' && results[4].reason);
        setClubLevel(1); // Fallback
      }

    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : "Đã có lỗi xảy ra khi tải dữ liệu bang hội.");
      toast.error("Không thể tải dashboard bang hội.");
    } finally {
      setLoading(false);
    }
  };

  const logAdminAction = async (message: string) => {
    await supabase.from('club_admin_logs').insert({
      club_id: clubId,
      actor_id: userId,
      message: message,
    });
  };

  const handleOpenEditModal = () => {
    if (!club) return;
    setEditingClubName(club.name);
    setEditingClubDesc(club.description || "");
    setEditingClubMinLevel(club.min_level_required || 1);
    setShowEditModal(true);
  };

  const handleUpdateClub = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!club || userId !== club.owner_id) {
      toast.error("Chỉ chủ bang mới có quyền này.");
      return;
    }

    const trimmedName = editingClubName.trim();
    const trimmedDesc = editingClubDesc.trim();

    if (!trimmedName || trimmedName.length < 3) {
      toast.error("Tên bang phải có ít nhất 3 ký tự.");
      return;
    }

    setIsUpdating(true);
    const toastId = toast.loading("Đang cập nhật thông tin bang...");

    try {
      const { error } = await supabase
        .from('clubs')
        .update({ name: trimmedName, description: trimmedDesc, min_level_required: editingClubMinLevel })
        .eq('id', clubId);

      if (error) throw error;

      await logAdminAction(`đã cập nhật thông tin bang hội.`);
      toast.success("Cập nhật thành công!", { id: toastId });
      setShowEditModal(false);
      // Cập nhật UI ngay lập tức
      setClub(prev => prev ? { ...prev, name: trimmedName, description: trimmedDesc, min_level_required: editingClubMinLevel } : null);
    } catch (err: unknown) {
      toast.error("Lỗi: " + (err instanceof Error ? err.message : String(err)), { id: toastId });
    } finally {
      setIsUpdating(false);
    }
  };

  const handleDisbandClub = async () => {
    if (!club || !userId || userId !== club.owner_id) {
      toast.error("Chỉ chủ bang mới có quyền giải tán bang.");
      return;
    }

    const { confirmDialog } = await import('@/store/useConfirmDialog');
    const ok = await confirmDialog({ title: 'Giải tán Bang hội', message: `Sếp có chắc chắn muốn giải tán bang "${club.name}" không? Hành động này không thể hoàn tác và sẽ xóa toàn bộ dữ liệu liên quan!`, confirmLabel: 'Giải tán', variant: 'danger' });
    if (!ok) return;

    setIsDisbanding(true);
    const toastId = toast.loading("Đang tiến hành giải tán bang hội...");

    try {
      // Sử dụng RPC để xóa trong một transaction duy nhất với ownership check
      const { error: rpcError } = await supabase.rpc('disband_club', {
        p_club_id: club.id,
      });

      if (rpcError) {
        throw rpcError;
      }

      toast.success(`Bang hội "${club.name}" đã được giải tán.`, { id: toastId });
      onBack(); // Quay về trang danh sách clubs
    } catch (err: unknown) {
      console.error("Lỗi giải tán bang:", err);
      toast.error("Không thể giải tán bang lúc này: " + (err instanceof Error ? err.message : String(err)), { id: toastId });
    } finally {
      setIsDisbanding(false);
    }
  };

  const handleSetRole = async (targetUserId: string, newRole: 'deputy' | 'member') => {
    if (!club || userId !== club.owner_id) {
      toast.error("Chỉ chủ bang mới có quyền này.");
      return;
    }
    if (targetUserId === userId) {
      toast.error("Sếp không thể tự thay đổi vai trò của mình.");
      return;
    }

    const toastId = toast.loading(`Đang ${newRole === 'deputy' ? 'bổ nhiệm' : 'hạ chức'}...`);
    try {
      const { error } = await supabase
        .from('club_members')
        .update({ role: newRole })
        .match({ club_id: clubId, user_id: targetUserId });

      if (error) throw error;

      // LOG ACTION
      const targetUserName = managingMember?.profiles?.nickname || 'thành viên';
      const message = newRole === 'deputy' 
        ? `đã bổ nhiệm ${targetUserName} làm Phó bang`
        : `đã hạ chức ${targetUserName} về làm thành viên`;
      await logAdminAction(message);

      toast.success("Cập nhật vai trò thành công!", { id: toastId });
      setManagingMember(null); // Close the menu
      fetchDashboard();
    } catch (err: unknown) {
      toast.error("Lỗi: " + (err instanceof Error ? err.message : String(err)), { id: toastId });
    }
  };

  const handleKickMember = async (targetUserId: string, targetUserName: string) => {
    const targetUser = leaders.find(l => l.user_id === targetUserId);
    if (!club || !isAdmin) {
      toast.error("Bạn không có quyền thực hiện hành động này.");
      return;
    }
    if (targetUserId === userId) {
      toast.error("Sếp không thể tự kick chính mình.");
      return;
    }
    if (currentUserRole === 'deputy' && (targetUser?.role === 'owner' || targetUser?.role === 'deputy')) {
      toast.error("Phó bang không thể mời người có chức vụ tương đương hoặc cao hơn ra khỏi bang.");
      return;
    }

    const { confirmDialog } = await import('@/store/useConfirmDialog');
    const ok = await confirmDialog({ title: 'Mời thành viên rời bang', message: `Bạn có chắc chắn muốn mời "${targetUserName}" ra khỏi bang không?`, confirmLabel: 'Xác nhận', variant: 'danger' });
    if (!ok) return;

    const toastId = toast.loading(`Đang xử lý...`);
    try {
      const { error } = await supabase.from('club_members').delete().match({ club_id: clubId, user_id: targetUserId });
      if (error) throw error;

      await logAdminAction(`đã mời ${targetUserName} ra khỏi bang`);

      toast.success(`Đã mời "${targetUserName}" ra khỏi bang.`, { id: toastId });
      setManagingMember(null);
      fetchDashboard();
    } catch (err: unknown) {
      toast.error("Lỗi: " + (err instanceof Error ? err.message : String(err)), { id: toastId });
    }
  };

  useEffect(() => {
    if (!clubId) return;
    fetchDashboard();

    const channel = supabase.channel(`club-${clubId}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "club_activity",
          filter: `club_id=eq.${clubId}`,
        },
        (payload: Record<string, unknown>) => {
          console.log('New activity received!', payload);
          fetchDashboard(); // Refetch all for simplicity, can be optimized later
        }
      )
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "club_admin_logs",
          filter: `club_id=eq.${clubId}`,
        },
        (payload: Record<string, unknown>) => {
          console.log('New admin log received!', payload);
          fetchDashboard(); // Refetch all
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [clubId]);

  const getRankStyle = (index: number) => {
    if (index === 0) return "bg-yellow-500/10 border border-yellow-500/30";
    if (index === 1) return "bg-slate-300/10 border border-slate-300/20";
    if (index === 2) return "bg-orange-500/10 border border-orange-500/20";
    return "bg-white/5 border border-white/5";
  };

  const getRankIcon = (index: number) => {
    if (index === 0) return <Crown className="text-yellow-400" size={18} />;
    if (index === 1) return <Medal className="text-slate-300" size={18} />;
    if (index === 2) return <Medal className="text-orange-400" size={18} />;
    return <span className="text-slate-500 font-bold">#{index + 1}</span>;
  };

  if (loading) {
    return (
      <div className="w-full h-full flex flex-col items-center justify-center bg-slate-950">
        <Loader2 size={32} className="animate-spin text-cyan-400" />
        <p className="text-slate-500 mt-3 text-sm">Đang tải dữ liệu bang hội...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="w-full h-full flex flex-col items-center justify-center bg-slate-950 p-8 text-center">
        <AlertTriangle size={40} className="text-red-500 mb-4" />
        <h3 className="text-xl font-bold text-white mb-2">Lỗi Tải Dữ Liệu</h3>
        <p className="text-slate-400 text-sm mb-6">{error}</p>
        <button onClick={onBack} className="px-6 py-2 bg-white/10 text-white rounded-lg font-semibold">Quay lại</button>
      </div>
    );
  }

  return (
    <>
      <div className="sticky top-0 z-10 bg-slate-950/90 backdrop-blur-lg border-b border-white/5 p-4 flex items-center gap-3">
        <button
          onClick={onBack}
          className="p-2 rounded-xl bg-white/5 text-white active:scale-95 transition-transform"
        >
          <ChevronLeft size={18} />
        </button>

        <h2 className="text-white font-bold">
          {club?.name || "Đang tải..."}
        </h2>

        <div className="ml-3 flex items-center gap-1.5 text-cyan-400 text-xs font-bold bg-cyan-400/10 px-3 py-1.5 rounded-lg border border-cyan-400/20">
          <Shield size={14} /> Cấp {clubLevel}
        </div>

        {userId === club?.owner_id && (
          <button
            onClick={handleOpenEditModal}
            className="ml-auto p-2 rounded-xl bg-white/5 text-slate-400 hover:text-cyan-400 active:scale-95 transition-all"
          >
            <Edit2 size={16} />
          </button>
        )}
      </div>

      <div className="p-4 space-y-6">
        {/* Club Info Header - LUÔN LUÔN HIỂN THỊ */}
        <div className="bg-slate-900/50 border border-white/5 rounded-3xl p-5 shadow-lg">
          <h2 className="text-white text-xl font-black">{club?.name}</h2>
          <p className="text-slate-400 text-sm mt-1">
            {club?.description || "Không có mô tả"}
          </p>

          <div className="mt-5">
            <div className="flex justify-between text-xs text-slate-400 mb-2">
              <span>Tiến độ bang hội</span>
              <span className="font-bold text-cyan-400">
                {totalMl.toLocaleString()} / {goal.toLocaleString()} ml
              </span>
            </div>

            <div className="w-full h-3 rounded-full bg-slate-800 overflow-hidden">
              <div
                className="h-full bg-cyan-400 rounded-full transition-all duration-1000 ease-out shadow-[0_0_10px_rgba(34,211,238,0.5)]"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>
        </div>

        {/* BỘ NÚT CHUYỂN TAB */}
        <div className="flex bg-slate-900/80 p-1.5 rounded-2xl border border-white/5">
          <button
            onClick={() => setTab('overview')}
            className={`flex-1 py-3 rounded-xl flex items-center justify-center gap-2 text-sm font-bold transition-all ${
              tab === 'overview' ? 'bg-cyan-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-white'
            }`}
          >
            <LayoutDashboard size={18} /> Tổng quan
          </button>
          <button
            onClick={() => setTab('chat')}
            className={`flex-1 py-3 rounded-xl flex items-center justify-center gap-2 text-sm font-bold transition-all ${
              tab === 'chat' ? 'bg-cyan-500 text-slate-950 shadow-md' : 'text-slate-400 hover:text-white'
            }`}
          >
            <MessageSquare size={18} /> Trò chuyện
          </button>
          {isAdmin && (
            <button
              onClick={() => setTab('admin')}
              className={`flex-1 py-3 rounded-xl flex items-center justify-center gap-2 text-sm font-bold transition-all ${
                tab === 'admin' ? 'bg-red-500/80 text-white shadow-md' : 'text-slate-400 hover:text-white'
              }`}
            >
              <Shield size={18} /> Quản trị
            </button>
          )}
        </div>

        {/* NỘI DUNG TÙY THEO TAB ĐƯỢC CHỌN */}
        {tab === 'overview' ? (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
            {/* Leaderboard */}
            <div className="space-y-3">
              <h3 className="text-white font-bold flex items-center gap-2">
                <Trophy className="text-yellow-400" size={18} />
                Leaderboard hôm nay
              </h3>

              {leaders.length === 0 ? (
                <div className="text-center p-6 rounded-2xl bg-white/5 text-slate-400 text-sm">
                  Bang hội chưa có hoạt động hôm nay, hãy là người đầu tiên tu nước nào 🔥
                </div>
              ) : (
                leaders.map((user, index) => (
                  <div
                    key={user.user_id}
                    className={`flex items-center justify-between p-4 rounded-2xl ${getRankStyle(index)}`}
                  >
                    <div className="flex items-center gap-3">
                      {getRankIcon(index)}
                      <div>
                        <p className="text-white font-semibold flex items-center gap-2">
                          {user.profiles?.nickname || "Ẩn danh"}
                          {user.role === 'owner' && <Crown size={14} className="text-yellow-400" />}
                          {user.role === 'deputy' && <Shield size={14} className="text-cyan-400" />}
                        </p>
                        <p className="text-xs text-cyan-400 font-medium">
                          {user.total_ml.toLocaleString()} ml
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                      {index === 0 && (
                        <Flame className="text-yellow-400 animate-pulse" size={18} />
                      )}
                      {isAdmin && user.user_id !== userId && !(currentUserRole === 'deputy' && user.role !== 'member') && (
                        <button onClick={() => setManagingMember(user)} className="p-2 rounded-full hover:bg-white/10 text-slate-500">
                          <MoreVertical size={18} />
                        </button>
                      )}
                    </div>
                  </div>
                ))
              )}
            </div>

            {/* Activity Feed */}
            <div className="space-y-3 pb-10">
              <h3 className="text-white font-bold flex items-center gap-2">
                <Droplets className="text-cyan-400" size={18} />
                Hoạt động gần đây
              </h3>

              <div className="space-y-2">
                {activities.map((item) => (
                  <div
                    key={item.id}
                    className="p-3 rounded-2xl bg-slate-900/40 border border-white/5 flex flex-col"
                  >
                    <p className="text-sm text-white">
                      <span className="font-semibold text-cyan-400">
                        {item.profiles?.nickname || "Ai đó"}
                      </span>{" "}
                      {item.message}
                    </p>

                    <p className="text-[10px] text-slate-500 mt-1 self-end">
                      {new Date(item.created_at).toLocaleTimeString("vi-VN", { hour: '2-digit', minute: '2-digit' })}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        ) : tab === 'chat' ? (
          /* TAB TRÒ CHUYỆN (CLUB CHAT) */
          <div className="h-[60vh] animate-in fade-in slide-in-from-bottom-2 duration-300">
            <ClubChat clubId={clubId} userId={userId} />
          </div>
        ) : (
          /* TAB QUẢN TRỊ */
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
            <div className="space-y-3">
              <h3 className="text-white font-bold flex items-center gap-2">
                <History className="text-slate-400" size={18} />
                Nhật ký quản trị
              </h3>
              <div className="space-y-2 max-h-[40vh] overflow-y-auto pr-2 scrollbar-thin scrollbar-thumb-slate-700">
                {adminLogs.map(log => (
                  <div key={log.id} className="p-3 rounded-xl bg-slate-900/40 border border-white/5 text-sm">
                    <span className="font-bold text-cyan-400">Hệ thống</span>
                    <span className="text-slate-300"> {log.action}</span>
                    <p className="text-[10px] text-slate-500 mt-1 text-right">{new Date(log.created_at).toLocaleString('vi-VN')}</p>
                  </div>
                ))}
              </div>
            </div>

            {/* KHU VỰC NGUY HIỂM CHO CHỦ BANG */}
            {userId === club?.owner_id && (
              <div className="mt-8 pt-6 border-t border-red-500/20">
                <h3 className="text-red-400 font-bold text-center mb-3 text-sm uppercase tracking-widest flex items-center justify-center gap-2">
                  <ShieldAlert size={16} /> Khu vực nguy hiểm
                </h3>
                <button
                  onClick={handleDisbandClub}
                  disabled={isDisbanding}
                  className="w-full py-3 rounded-xl bg-red-500/10 border border-red-500/30 text-red-400 font-bold text-sm hover:bg-red-500/20 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isDisbanding ? <Loader2 className="animate-spin" /> : 'Giải tán Bang hội'}
                </button>
              </div>
            )}
          </div>
        )}
      </div>

      <AnimatePresence>
        {managingMember && (
          <div className="fixed inset-0 z-[110] flex items-end justify-center">
            <motion.div 
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              onClick={() => setManagingMember(null)}
              className="absolute inset-0 bg-black/60 backdrop-blur-sm" 
            />
            <motion.div
              initial={{ y: '100%' }} animate={{ y: 0 }} exit={{ y: '100%' }}
              className="relative z-10 w-full max-w-md bg-slate-900 border-t border-white/10 rounded-t-3xl p-6"
            >
              <h3 className="text-lg font-bold text-white mb-2">Quản lý thành viên</h3>
              <p className="text-slate-400 mb-6">Bạn đang quản lý: <span className="font-bold text-cyan-400">{managingMember.profiles?.nickname}</span></p>
              
              <div className="space-y-3">
                {managingMember.role !== 'deputy' && (
                  <button onClick={() => handleSetRole(managingMember.user_id, 'deputy')} className="w-full p-4 rounded-xl bg-cyan-500/10 text-cyan-400 font-bold flex items-center gap-3 hover:bg-cyan-500/20 transition-colors">
                    <Shield size={18} /> Bổ nhiệm làm Phó bang
                  </button>
                )}
                {managingMember.role === 'deputy' && (
                  <button onClick={() => handleSetRole(managingMember.user_id, 'member')} className="w-full p-4 rounded-xl bg-amber-500/10 text-amber-400 font-bold flex items-center gap-3 hover:bg-amber-500/20 transition-colors">
                    <User size={18} /> Hạ chức về Thành viên
                  </button>
                )}
                <button onClick={() => handleKickMember(managingMember.user_id, managingMember.profiles?.nickname || 'Thành viên này')} className="w-full p-4 rounded-xl bg-red-500/10 text-red-400 font-bold flex items-center gap-3 hover:bg-red-500/20 transition-colors">
                  <XCircle size={18} /> Mời khỏi bang
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showEditModal && (
          <div className="fixed inset-0 z-[150] flex items-center justify-center p-6">
            <motion.div
              initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              onClick={() => setShowEditModal(false)}
              className="absolute inset-0 bg-black/80 backdrop-blur-sm"
            />
            <motion.form
              initial={{ scale: 0.9, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.9, opacity: 0, y: 20 }}
              onSubmit={handleUpdateClub}
              className="relative w-full max-w-sm bg-slate-900 border border-white/10 p-7 rounded-[2.5rem] shadow-2xl space-y-5"
            >
              <div className="flex justify-between items-center">
                <h2 className="text-white font-black text-xl">Chỉnh sửa Bang hội</h2>
                <button type="button" onClick={() => setShowEditModal(false)} className="text-slate-500 hover:text-white">
                  <X size={20} />
                </button>
              </div>
              <div className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] uppercase tracking-widest text-slate-500 font-bold ml-1">Tên Bang Hội</label>
                  <input
                    value={editingClubName}
                    onChange={(e) => setEditingClubName(e.target.value)}
                    maxLength={50}
                    className="w-full bg-white/5 border border-white/5 rounded-2xl px-5 py-4 text-white outline-none focus:border-cyan-500/50 transition-all"
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] uppercase tracking-widest text-slate-500 font-bold ml-1">Khẩu Hiệu / Mô tả</label>
                  <textarea
                    value={editingClubDesc}
                    onChange={(e) => setEditingClubDesc(e.target.value)}
                    maxLength={200}
                    className="w-full bg-white/5 border border-white/5 rounded-2xl px-5 py-4 text-white h-28 resize-none outline-none focus:border-cyan-500/50 transition-all"
                  />
                </div>
                <div className="space-y-1.5">
                  <div className="flex justify-between items-center">
                    <label className="text-[10px] uppercase tracking-widest text-slate-500 font-bold ml-1">Cấp độ yêu cầu</label>
                    <span className="font-bold text-cyan-400">Lv.{editingClubMinLevel}</span>
                  </div>
                  <input
                    type="range" min="1" max="100"
                    value={editingClubMinLevel}
                    onChange={(e) => setEditingClubMinLevel(Number(e.target.value))}
                    className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                  />
                </div>
              </div>
              <button type="submit" disabled={isUpdating} className="w-full py-4 rounded-xl bg-cyan-500 text-black font-black text-sm shadow-lg shadow-cyan-500/20 active:scale-95 transition-transform disabled:opacity-50">
                {isUpdating ? <Loader2 className="animate-spin mx-auto" /> : "LƯU THAY ĐỔI"}
              </button>
            </motion.form>
          </div>
        )}
      </AnimatePresence>
    </>
  );
}

import { useEffect } from 'react';
import type { AppShellProps } from '@/app/AppShell';
import { useAppTabProps } from '@/app/useAppTabProps';
import type { TabType } from '@/components/layout/BottomNav';
import { useAiSocialOrchestration } from '@/features/app/useAiSocialOrchestration';
import { useAppUiState } from '@/features/app/useAppUiState';
import { useHydrationController } from '@/features/app/useHydrationController';
import { useLeagueController } from '@/features/app/useLeagueController';
import { updateProfileFields } from '@/services/profile.service';
import { useAppSystem } from '@/hooks/useAppSystem';
import { useReminderStore } from '@/store/useReminderStore';
import { useDrinkPresetStore } from '@/store/useDrinkPresetStore';
import { useAppStore } from '@/store/useAppStore';
import { getRankInfo } from '@/utils/healthMath';

export function useAppShellController(): AppShellProps {
  const {
    view = 'welcome',
    setView = () => { },
    profile = null,
    setProfile = () => { },
    loginPrefill = '',
    setLoginPrefill = () => { },
    handleLogout = async () => { },
    isWeatherSynced = false,
    setIsWeatherSynced = () => { },
    weatherData,
    isCalendarSynced = false,
    setIsCalendarSynced = () => { },
    isWatchConnected = false,
    watchData,
  } = useAppSystem() || {};

  const {
    activeTab,
    setActiveTab,
    setShowOnboarding,
    setShowPremiumModal,
    setShowProfileSettings,
    setShowAddFriend,
    setShowShopModal,
  } = useAppUiState();

  const { loadReminderSettings } = useReminderStore();
  const { loadDrinkPresets } = useDrinkPresetStore();
  const setAppState = useAppStore((state) => state.setAppState);
  const setAppActions = useAppStore((state) => state.setActions);

  const hydration = useHydrationController({
    profile,
    setProfile,
    view,
    weatherData,
    isWeatherSynced,
    setIsWeatherSynced,
    isCalendarSynced,
    setIsCalendarSynced,
    isWatchConnected,
    watchData,
    setShowOnboarding,
    setShowProfileSettings,
    setShowPremiumModal,
    loadReminderSettings,
    loadDrinkPresets,
  });

  const league = useLeagueController({
    profile,
    activeTab: activeTab as TabType,
    streak: hydration.streak,
    setShowAddFriend,
  });

  const {
    socialProps,
    geminiProps,
    posts,
    openSocialComposer,
  } = useAiSocialOrchestration();

  // ── Sync hydration data to Zustand store ──
  useEffect(() => {
    setAppState({
      profile,
      waterIntake: hydration.waterIntake,
      waterGoal: hydration.waterGoal,
      streak: hydration.streak,
      waterEntries: hydration.waterEntries,
      weeklyHistory: hydration.weeklyHistory,
      weatherData,
      watchData,
      isWeatherSynced,
      isWatchConnected,
      isSyncing: hydration.isSyncing,
      hasPendingCloudSync: hydration.hasPendingCloudSync,
      hydrationResult: hydration.hydrationResult,
      isPremium: hydration.isPremium,
      fastingState: {
        isFastingMode: hydration.isFastingMode,
        fastingPlanHours: hydration.fastingPlanHours,
        fastingTotalMs: hydration.fastingTotalMs,
        fastingStartTime: hydration.fastingStartTime,
      }
    });
  }, [
    hydration.hydrationResult,
    hydration.isPremium,
    hydration.streak,
    hydration.waterEntries,
    hydration.waterGoal,
    hydration.waterIntake,
    hydration.weeklyHistory,
    isWatchConnected,
    isWeatherSynced,
    profile,
    setAppState,
    watchData,
    weatherData,
  ]);

  useEffect(() => {
    setAppActions({
      handleAddWater: hydration.handleAddWater,
      handleDeleteEntry: hydration.handleDeleteEntry,
      handleEditEntry: hydration.handleEditEntry,
      handleLogout,
      openSocialComposer,
      startFasting: hydration.startFasting,
      stopFasting: hydration.stopFasting,
    });
  }, [
    handleLogout,
    hydration.handleAddWater,
    hydration.handleDeleteEntry,
    hydration.handleEditEntry,
    hydration.startFasting,
    hydration.stopFasting,
    openSocialComposer,
    setAppActions,
  ]);

  // ── Auto-navigate to home if bottle disconnects while on bottle tab ──
  useEffect(() => {
    const { isConnected, isSyncing } = hydration.smartBottle || {};
    if (activeTab === 'insight' && !isConnected && !isSyncing) {
      // Bottle demo redirect — show insight/coach instead
    }
  }, [activeTab, hydration.smartBottle?.isConnected, hydration.smartBottle?.isSyncing, setActiveTab]);

  // ── Sync tab props ──
  const tabProps = useAppTabProps({
    profile,
    smartBottle: hydration.smartBottle,
    isExportingPDF: hydration.isExportingPDF,
    handleExportPDF: hydration.handleExportPDF,
    handleExportCSV: hydration.handleExportCSV,
    geminiProps,
    weeklyReport: hydration.weeklyReport,
    isWeeklyReportLoading: hydration.isWeeklyReportLoading,
    handleGenerateWeeklyReport: hydration.handleGenerateWeeklyReport,
    weatherData,
    isWeatherSynced,
    watchData,
    isWatchConnected,
    leagueMode: league.leagueMode,
    setLeagueMode: league.setLeagueMode,
    setShowAddFriend,
    setShowShopModal,
    getLeagueData: league.getLeagueData,
    getRankInfo,
    socialProps,
    openSocialComposer,
    streakFreezes: hydration.streakFreezes,
    needsFreeze: hydration.needsFreeze,
    useStreakFreeze: hydration.useStreakFreeze,
    posts,
    setActiveTab,
  });

  return {
    view,
    setView,
    loginPrefill,
    handleRegisterSuccess: (email: string) => {
      setLoginPrefill(email);
      setView('login');
    },
    profile,
    handleLogout,
    quickDropCameraProps: {
      isOpen: !!socialProps.showQuickDropCamera,
      isPublishing: !!socialProps.isPublishingQuickDrop,
      onCapture: socialProps.handleQuickDropCapture || (async () => {}),
      onClose: socialProps.closeQuickDropCamera || (() => {}),
    },
    onboardingProps: profile && !profile.onboarding_completed ? {
      profile,
      onComplete: async (weight: number, onboardingWaterGoal: number, name: string) => {
        setProfile((prev: Record<string, unknown> | null) => ({
          ...prev,
          weight,
          water_goal: onboardingWaterGoal,
          nickname: name,
          onboarding_completed: true,
        }));
        await updateProfileFields(profile.id, {
          nickname: name.trim(),
          onboarding_completed: true,
          water_goal: onboardingWaterGoal,
          weight,
        });
      },
    } : null,
    activeTab: activeTab as TabType,
    setActiveTab,
    homeTabProps: tabProps.homeTabProps,
    insightTabProps: tabProps.insightTabProps,
    bottleTabProps: tabProps.bottleTabProps,
    leagueTabProps: tabProps.leagueTabProps,
    feedTabProps: tabProps.feedTabProps,
    profileTabProps: tabProps.profileTabProps,
    devSyncProps: {
      visible: import.meta.env.DEV && !!profile?.id && profile.id !== 'undefined',
      onClick: hydration.syncProfileData,
    },
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { toast } from 'sonner';
import { supabase } from '@/lib/supabase';
import type { HealthReport } from '@/lib/aiReports';
import { generateWeeklyReport, getLatestHealthReport } from '@/lib/aiReports';
import { provisionUserQuests, runChallengeEngine, runQuestEngine } from '@/lib/questEngine';
import { playSuccessSound } from '@/lib/audio';
// @ts-expect-error - canvas-confetti has no types
import confetti from 'canvas-confetti';

import { AppStorage } from '@/lib/storage';

interface UsePremiumGamificationOptions {
  profile: Record<string, unknown> | null;
  setProfile: React.Dispatch<React.SetStateAction<Record<string, unknown> | null>>;
  isPremium: boolean;
  setIsPremium: (value: boolean) => void;
  waterIntake: number;
  waterGoal: number;
  streak: number;
  waterEntries: Record<string, unknown>[];
  weeklyHistory: { d: string; ml: number; isToday: boolean }[];
  weeklyLogCount: number;
  watchData: Record<string, unknown> | null;
  setShowPremiumModal: (value: boolean) => void;
}

export function usePremiumGamification({
  profile,
  isPremium,
  setIsPremium,
  waterIntake,
  waterGoal,
  streak,
  waterEntries,
  weeklyHistory,
  weeklyLogCount,
  watchData,
  setShowPremiumModal,
}: UsePremiumGamificationOptions) {
  const previousLevelRef = useRef<number | null>(null);
  const [showLevelUp, setShowLevelUp] = useState(false);
  const [levelUpInfo, setLevelUpInfo] = useState({ from: 0, to: 0 });
  const [weeklyReport, setWeeklyReport] = useState<HealthReport | null>(null);
  const [isWeeklyReportLoading, setIsWeeklyReportLoading] = useState(false);

  const syncPremiumStatus = useCallback(async (options?: { poll?: boolean }) => {
    if (!profile?.id || profile.id === 'undefined') {
      setIsPremium(false);
      return false;
    }

    const attempts = options?.poll ? 5 : 1;

    for (let attempt = 0; attempt < attempts; attempt += 1) {
      const { data, error } = await supabase
        .from('profiles')
        .select('subscription_tier, subscription_end')
        .eq('id', profile.id)
        .single();

      if (!error && data) {
        const endDate = data.subscription_end ? new Date(data.subscription_end) : null;
        const premiumActive = data.subscription_tier === 'premium' && (!endDate || endDate > new Date());

        setIsPremium(premiumActive);

        if (premiumActive || !options?.poll) {
          return premiumActive;
        }
      }

      if (attempt < attempts - 1) {
        await new Promise(resolve => setTimeout(resolve, 1500));
      }
    }

    setIsPremium(false);
    return false;
  }, [profile?.id]);

  useEffect(() => {
    void syncPremiumStatus();
  }, [syncPremiumStatus]);

  useEffect(() => {
    if (!profile?.id || profile.id === 'undefined' || !isPremium) {
      setWeeklyReport(null);
      return;
    }

    let ignore = false;

    const loadLatestWeeklyReport = async () => {
      setIsWeeklyReportLoading(true);

      try {
        const latestReport = await getLatestHealthReport(profile.id, 'weekly');
        if (!ignore) {
          setWeeklyReport(latestReport);
        }
      } finally {
        if (!ignore) {
          setIsWeeklyReportLoading(false);
        }
      }
    };

    void loadLatestWeeklyReport();

    return () => {
      ignore = true;
    };
  }, [profile?.id, isPremium]);

  useEffect(() => {
    if (!profile?.level || previousLevelRef.current === null || profile.level <= previousLevelRef.current) {
      previousLevelRef.current = profile?.level || null;
      return;
    }

    const newLevel = profile.level;
    const isMilestone10 = newLevel % 10 === 0;

    setLevelUpInfo({ from: previousLevelRef.current, to: newLevel });
    setShowLevelUp(true);
    confetti({ particleCount: isMilestone10 ? 400 : 200, spread: 120, origin: { y: 0.6 }, zIndex: 9999 });
    playSuccessSound();

    setTimeout(() => {
      toast.success(`🎉 Lên cấp ${newLevel}! Thành tích đã được ghi nhận.`, { icon: '⭐', duration: 5000 });
    }, 500);

    previousLevelRef.current = profile.level;
  }, [profile]);

  useEffect(() => {
    if (!profile?.id || profile.id === 'undefined' || waterIntake < waterGoal || waterGoal === 0) return;

    const storageKey = `awarded_100pct_badge_${profile.id}`;
    if (AppStorage.getItem(storageKey)) return;

    const awardFirst100PercentBadge = async () => {
      try {
        const { data: badgeData } = await supabase.from('badges').select('id').eq('name', 'Giọt Nước Nhỏ').single();
        if (!badgeData) return;

        const { data: userBadge } = await supabase
          .from('user_badges')
          .select('id')
          .eq('user_id', profile.id)
          .eq('badge_id', badgeData.id)
          .single();

        if (!userBadge) {
          const { error } = await supabase.from('user_badges').insert({
            user_id: profile.id,
            badge_id: badgeData.id,
          });

          if (!error) {
            toast.success('🎉 Bạn đã nhận được Huy hiệu: Giọt Nước Nhỏ!');
            AppStorage.setItem(storageKey, 'true');
          }
          return;
        }

        AppStorage.setItem(storageKey, 'true');
      } catch (error) {
        console.error('Lỗi khi kiểm tra và trao huy hiệu:', error);
      }
    };

    void awardFirst100PercentBadge();
  }, [profile?.id, waterGoal, waterIntake]);

  useEffect(() => {
    if (!profile?.id || profile.id === 'undefined') return;

    const assignQuestsIfNeeded = async () => {
      const todayStr = new Date().toISOString().split('T')[0];
      const lastCheckKey = `daily_quest_check_v3_${profile.id}`;
      const lastCheckDate = AppStorage.getItem(lastCheckKey);

      if (lastCheckDate === todayStr) return;

      try {
        await supabase.rpc('assign_daily_quests', { p_user_id: profile.id });
        await provisionUserQuests(profile.id, profile.level || 1);
        AppStorage.setItem(lastCheckKey, todayStr);
      } catch (error) {
        console.error('Lỗi khi gán nhiệm vụ hàng ngày:', error);
      }
    };

    void assignQuestsIfNeeded();
  }, [profile?.id, profile?.level]);

  useEffect(() => {
    if (!profile?.id || waterGoal === 0 || waterIntake < waterGoal) return;

    const todayStr = new Date().toISOString().split('T')[0];
    const soundKey = `digiwell_100pct_sound_${profile.id}_${todayStr}`;

    if (AppStorage.getItem(soundKey)) return;

    playSuccessSound();
    if (navigator.vibrate) {
      navigator.vibrate([100, 50, 100, 50, 200]);
    }

    confetti({
      particleCount: 150,
      spread: 100,
      origin: { y: 0.5 },
      zIndex: 9999,
      colors: ['#06b6d4', '#f59e0b', '#10b981', '#a855f7'],
    });

    AppStorage.setItem(soundKey, 'true');
  }, [profile?.id, waterGoal, waterIntake]);

  useEffect(() => {
    if (!profile?.id || !profile.onboarding_completed) return;

    const questCtx = {
      userId: profile.id,
      waterToday: waterIntake,
      waterGoal,
      streak,
      totalWater: profile.total_water || 0,
      logCountToday: waterEntries.length,
      weeklyDays: weeklyHistory.filter(item => item.ml >= waterGoal).length,
      weeklyWater: weeklyHistory.reduce((sum, item) => sum + item.ml, 0),
      weeklyLogCount,
      equippedSound: profile.equipped_notification_sound,
      level: profile.level || 1,
    };

    runQuestEngine(questCtx);
    runChallengeEngine(questCtx);
  }, [
    profile?.equipped_notification_sound,
    profile?.id,
    profile?.level,
    profile?.onboarding_completed,
    profile?.total_water,
    streak,
    waterEntries.length,
    waterGoal,
    waterIntake,
    weeklyHistory,
    weeklyLogCount,
  ]);

  const handleGenerateWeeklyReport = useCallback(async () => {
    if (!profile?.id || profile.id === 'undefined') return;

    if (!isPremium) {
      setShowPremiumModal(true);
      return;
    }

    setIsWeeklyReportLoading(true);
    const toastId = toast.loading('AI đang tạo báo cáo tuần...');

    try {
      const report = await generateWeeklyReport(profile.id, {
        nickname: profile.nickname,
        goal: profile.goal,
        activity: profile.activity,
        avgHeartRate: watchData?.heartRate,
      });

      setWeeklyReport(report);
      toast.success('Đã tạo báo cáo tuần thành công.', { id: toastId });
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Không thể tạo báo cáo tuần lúc này.';
      toast.error(message, { id: toastId });
    } finally {
      setIsWeeklyReportLoading(false);
    }
  }, [isPremium, profile, setShowPremiumModal, watchData?.heartRate]);

  return {
    showLevelUp,
    setShowLevelUp,
    levelUpInfo,
    weeklyReport,
    isWeeklyReportLoading,
    handleGenerateWeeklyReport,
    syncPremiumStatus,
  };
}

/* eslint-disable react-refresh/only-export-components */
import { useState, useEffect, useCallback, useRef } from 'react';
import { Capacitor } from '@capacitor/core';
import { Browser } from '@capacitor/browser';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';
import { useAppStore } from '../store/useAppStore';

export const CALENDAR_OAUTH_PENDING_KEY = 'digiwell_pending_calendar_oauth';
export const CALENDAR_TOKEN_UPDATED_EVENT = 'digiwell:google-provider-token-updated';
const CALENDAR_CACHE_KEY = 'digiwell_calendar_events_cache';
const CALENDAR_SYNCED_KEY = 'digiwell_calendar_synced_flag';
const CALENDAR_REFRESH_TOKEN_KEY = 'digiwell_google_refresh_token';

const GOOGLE_CALENDAR_SCOPE = 'https://www.googleapis.com/auth/calendar.readonly';
const CALENDAR_SYNC_TOAST_ID = 'digiwell-calendar-sync-toast';
const CALENDAR_OAUTH_MODE_KEY = 'digiwell_calendar_oauth_mode';

export interface CalendarEventItem {
  id: string;
  title: string;
  start: string;
  end: string;
  startRaw: string;
  endRaw: string;
  isAllDay: boolean;
  status?: string;
  transparency?: string;
  htmlLink?: string;
}

type CalendarOAuthOptions = {
  provider: 'google';
  options: {
    redirectTo: string;
    skipBrowserRedirect: boolean;
    scopes: string;
    queryParams: {
      access_type: string;
      prompt: string;
      include_granted_scopes: string;
    };
  };
};

type GoogleEventDateTime = {
  date?: string;
  dateTime?: string;
};

type GoogleCalendarEvent = {
  id?: string;
  summary?: string;
  htmlLink?: string;
  status?: string;
  transparency?: string;
  start?: GoogleEventDateTime;
  end?: GoogleEventDateTime;
};

type CalendarOAuthMode = 'link' | 'signin';

type CalendarProxyResponse = {
  events?: GoogleCalendarEvent[];
  needs_reauth?: boolean;
  error?: string;
};

function getOAuthRedirectTo() {
  return Capacitor.isNativePlatform() ? 'digiwell://login-callback' : window.location.origin;
}

function readCalendarOAuthPendingFlag() {
  return window.sessionStorage.getItem(CALENDAR_OAUTH_PENDING_KEY) === 'true'
    || localStorage.getItem(CALENDAR_OAUTH_PENDING_KEY) === 'true';
}

function writeCalendarOAuthPendingFlag(value: boolean) {
  if (value) {
    window.sessionStorage.setItem(CALENDAR_OAUTH_PENDING_KEY, 'true');
    localStorage.setItem(CALENDAR_OAUTH_PENDING_KEY, 'true');
    return;
  }
  window.sessionStorage.removeItem(CALENDAR_OAUTH_PENDING_KEY);
  localStorage.removeItem(CALENDAR_OAUTH_PENDING_KEY);
}

function getDisplayTime(date: GoogleEventDateTime | undefined, isEnd = false) {
  if (!date) return '--';
  if (date.dateTime) {
    return new Intl.DateTimeFormat('vi-VN', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    }).format(new Date(date.dateTime));
  }
  if (date.date) {
    if (isEnd) return '23:59';
    return '00:00';
  }
  return '--';
}

function mapGoogleEvent(event: GoogleCalendarEvent): CalendarEventItem | null {
  // Chỉ lọc ra các sự kiện đang hoạt động
  if (event.status === 'cancelled') return null;

  // Note: Một số người dùng set lịch là "Rảnh" (transparent) nhưng vẫn muốn thấy nó.
  // Nếu muốn bỏ qua các lịch rảnh hoàn toàn, có thể uncomment dòng dưới:
  // if (event.transparency === 'transparent') return null;

  const isAllDay = !!event.start?.date && !event.start?.dateTime;
  const startRaw = event.start?.dateTime || event.start?.date || '';
  const endRaw = event.end?.dateTime || event.end?.date || '';
  if (!event.id || !startRaw) return null;

  return {
    id: event.id,
    title: event.summary?.trim() || 'Sự kiện không tên',
    start: getDisplayTime(event.start),
    end: getDisplayTime(event.end, true),
    startRaw,
    endRaw,
    isAllDay,
    status: event.status,
    transparency: event.transparency,
    htmlLink: event.htmlLink,
  };
}

function writeCalendarOAuthMode(mode: CalendarOAuthMode | null) {
  if (mode) {
    window.sessionStorage.setItem(CALENDAR_OAUTH_MODE_KEY, mode);
    localStorage.setItem(CALENDAR_OAUTH_MODE_KEY, mode);
    return;
  }
  window.sessionStorage.removeItem(CALENDAR_OAUTH_MODE_KEY);
  localStorage.removeItem(CALENDAR_OAUTH_MODE_KEY);
}

async function beginGoogleCalendarOAuth(options: { forceSignIn?: boolean } = {}) {
  const { data: { user }, error: userError } = await supabase.auth.getUser();
  if (userError) throw userError;
  if (!user) throw new Error('Vui lòng đăng nhập trước khi kết nối Google Calendar.');
  writeCalendarOAuthPendingFlag(true);
  const credentials: CalendarOAuthOptions = {
    provider: 'google' as const,
    options: {
      redirectTo: getOAuthRedirectTo(),
      skipBrowserRedirect: Capacitor.isNativePlatform(),
      scopes: GOOGLE_CALENDAR_SCOPE,
      queryParams: {
        access_type: 'offline',
        prompt: 'consent',
        include_granted_scopes: 'true',
      },
    },
  };
  const hasGoogleIdentity = user.identities?.some((identity: { provider?: string }) => identity.provider === 'google');
  const shouldSignIn = options.forceSignIn || hasGoogleIdentity;
  writeCalendarOAuthMode(shouldSignIn ? 'signin' : 'link');
  const response = shouldSignIn
    ? await supabase.auth.signInWithOAuth(credentials)
    : await supabase.auth.linkIdentity(credentials);
  if (response.error) throw response.error;
  if (Capacitor.isNativePlatform() && response.data?.url) {
    await Browser.open({ url: response.data.url });
  }
}

async function fetchCalendarEventsViaProxy(): Promise<CalendarProxyResponse> {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session?.access_token) {
    return { events: [], needs_reauth: true };
  }

  // 1. Persist refresh_token khi có (chỉ xuất hiện lần đầu sau OAuth)
  if (session.provider_refresh_token) {
    localStorage.setItem(CALENDAR_REFRESH_TOKEN_KEY, session.provider_refresh_token);
    // Lưu lên DB để đồng bộ xuyên thiết bị
    const { data: { user } } = await supabase.auth.getUser();
    if (user) {
      await supabase.from('profiles').update({ google_refresh_token: session.provider_refresh_token }).eq('id', user.id);
      await supabase.from('public_profiles').update({ is_calendar_synced: true }).eq('id', user.id);
    }
  }

  // 2. Lấy refresh token (Ưu tiên local -> rồi đến DB)
  let refreshToken = session.provider_refresh_token || localStorage.getItem(CALENDAR_REFRESH_TOKEN_KEY);

  if (!refreshToken) {
    const { data: profile } = await supabase.from('profiles').select('google_refresh_token').single();
    refreshToken = profile?.google_refresh_token || '';
    if (refreshToken) localStorage.setItem(CALENDAR_REFRESH_TOKEN_KEY, refreshToken);
  }

  const timeMin = new Date();
  timeMin.setHours(0, 0, 0, 0);
  const { data, error } = await supabase.functions.invoke('calendar-proxy', {
    body: {
      action: 'list-events',
      maxResults: 50,
      daysAhead: 7,
      timeMin: timeMin.toISOString(),
      providerToken: session.provider_token || '',
      providerRefreshToken: refreshToken,
    },
  });
  if (error) throw new Error(error.message || 'Không thể kết nối calendar proxy.');
  const response = data as CalendarProxyResponse | null;
  if (response?.error) {
    if (response.error.includes('unauthorized') || response.error.includes('invalid_grant')) {
      return { events: [], needs_reauth: true };
    }
    throw new Error(response.error);
  }
  return response ?? { events: [], needs_reauth: true };
}

const SYNC_COOLDOWN_MS = 1 * 60 * 1000; // Giảm cooldown xuống 1 phút

export function useCalendarSync() {
  const profile = useAppStore(s => s.profile);
  const isCalendarSynced = useAppStore(s => s.isCalendarSynced);
  const calendarEvents = useAppStore(s => s.calendarEvents);

  const [isSyncing, setIsSyncing] = useState(false);
  const retryTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const retryCountRef = useRef(0);
  const lastSyncTimeRef = useRef<number>(0);

  const setIsCalendarSynced = useCallback((synced: boolean) => {
    useAppStore.getState().setAppState({ isCalendarSynced: synced });
    localStorage.setItem(CALENDAR_SYNCED_KEY, synced ? 'true' : 'false');

    // Lưu vào DB để ghi nhớ vĩnh viễn
    const userId = useAppStore.getState().profile?.id;
    if (userId) {
      supabase.from('public_profiles').update({ is_calendar_synced: synced }).eq('id', userId).then();
    }
  }, []);

  const clearRetry = useCallback(() => {
    if (retryTimerRef.current) {
      clearTimeout(retryTimerRef.current);
      retryTimerRef.current = null;
    }
    retryCountRef.current = 0;
    toast.dismiss(CALENDAR_SYNC_TOAST_ID);
  }, []);

  const syncCalendar = useCallback(async (
    options: { silent?: boolean; startOAuthIfNeeded?: boolean } = {},
  ): Promise<number | false> => {
    const { silent = false, startOAuthIfNeeded = true } = options;
    const now = Date.now();

    if (lastSyncTimeRef.current > 0 && now - lastSyncTimeRef.current < SYNC_COOLDOWN_MS) {
      return calendarEvents.length;
    }

    const tid = silent ? '' : toast.loading('Đang cập nhật lịch Google...', { id: CALENDAR_SYNC_TOAST_ID });
    if (!silent) setIsSyncing(true);

    try {
      const proxyResponse = await fetchCalendarEventsViaProxy();
      lastSyncTimeRef.current = Date.now();

      if (proxyResponse.needs_reauth) {
        setIsSyncing(false);

        // GIỮ LẠI LỊCH CŨ: Nếu đã có dữ liệu cached, không được set isCalendarSynced = false
        const hasCachedEvents = calendarEvents.length > 0 || localStorage.getItem(CALENDAR_CACHE_KEY);
        if (hasCachedEvents) {
          // Vẫn coi như đã đồng bộ để UI hiện lịch cũ
          setIsCalendarSynced(true);
          return calendarEvents.length;
        }

        // Chỉ khi chưa bao giờ sync thành công mới bắt re-auth
        if (!startOAuthIfNeeded) return false;
        await beginGoogleCalendarOAuth();
        return false;
      }

      const events = (proxyResponse.events || [])
        .map(mapGoogleEvent)
        .filter((event): event is CalendarEventItem => !!event);

      const store = useAppStore.getState();
      const newEventsStr = JSON.stringify(events);

      // Cập nhật dữ liệu mới nhất
      store.setAppState({ 
        calendarEvents: events,
        isCalendarSynced: true 
      });
      localStorage.setItem(CALENDAR_CACHE_KEY, newEventsStr);
      localStorage.setItem(CALENDAR_SYNCED_KEY, 'true');

      clearRetry();
      writeCalendarOAuthPendingFlag(false);

      if (!silent) {
        toast.success(
          events.length > 0
            ? `Đã đồng bộ ${events.length} sự kiện mới nhất.`
            : 'Lịch trình trống.',
          { id: tid },
        );
      }
      setIsSyncing(false);
      return events.length;
    } catch (error) {
      if (!silent) {
        const message = error instanceof Error ? error.message : 'Lỗi đồng bộ.';
        toast.error(message, { id: tid });
      }
      setIsSyncing(false);
      return false;
    }
  }, [calendarEvents.length, clearRetry, setIsCalendarSynced]);

  const scheduleRetry = useCallback(() => {
    clearRetry();
    const retry = async () => {
      retryCountRef.current++;
      const attempt = retryCountRef.current;
      const result = await syncCalendar({ silent: true, startOAuthIfNeeded: false });
      if (result !== false) return;
      if (attempt < 3) {
        retryTimerRef.current = setTimeout(retry, Math.min(1500 * attempt, 6000));
      } else {
        writeCalendarOAuthPendingFlag(false);
        clearRetry();
      }
    };
    retryTimerRef.current = setTimeout(retry, 1000);
  }, [syncCalendar, clearRetry]);

  useEffect(() => {
    // 1. Khôi phục từ Cache ngay lập tức
    const cachedEvents = localStorage.getItem(CALENDAR_CACHE_KEY);
    const cachedSynced = localStorage.getItem(CALENDAR_SYNCED_KEY) === 'true';
    if (cachedEvents || cachedSynced) {
      useAppStore.getState().setAppState({
        calendarEvents: cachedEvents ? JSON.parse(cachedEvents) : [],
        isCalendarSynced: cachedSynced
      });
    }

    // 2. Tự động quét mới - Chờ Profile có dữ liệu
    const initSync = async () => {
      if (!profile?.id) return; // Chờ cho đến khi có profile

      const isPending = readCalendarOAuthPendingFlag();
      if (isPending) {
        scheduleRetry();
        return;
      }

      // Kiểm tra trạng thái đồng bộ từ DB (Ghi nhớ xuyên trình duyệt)
      const profileSynced = profile?.is_calendar_synced;
      if (cachedSynced || profileSynced) {
        if (profileSynced && !cachedSynced) {
           useAppStore.getState().setAppState({ isCalendarSynced: true });
        }
        await syncCalendar({ silent: true, startOAuthIfNeeded: false });
      }
    };

    void initSync();

    const handleTokenUpdated = () => scheduleRetry();
    window.addEventListener(CALENDAR_TOKEN_UPDATED_EVENT, handleTokenUpdated);

    return () => {
      window.removeEventListener(CALENDAR_TOKEN_UPDATED_EVENT, handleTokenUpdated);
      clearRetry();
    };
  }, [profile?.id, profile?.is_calendar_synced]); // Chạy lại khi Profile tải xong

  return { isCalendarSynced, setIsCalendarSynced, calendarEvents, syncCalendar, isSyncing };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';

export function useClubs(userId?: string) {
  const [myClub, setMyClub] = useState<Record<string, unknown> | null>(null);
  const [allClubs, setAllClubs] = useState<Record<string, unknown>[]>([]);
  const [loading, setLoading] = useState(false);
  const [joining, setJoining] = useState(false);

  // =========================
  // LOAD DATA
  // =========================
  const fetchClubData = useCallback(async () => {
    if (!userId) {
      setMyClub(null);
      setAllClubs([]);
      return;
    }

    setLoading(true);

    try {
      // user current club
      const { data: memberData, error: memberError } = await supabase
        .from('club_members')
        .select(`
          role,
          club_id,
          clubs (
            id,
            name,
            description,
            avatar_url,
            owner_id,
            daily_goal,
            is_private,
            created_at
          )
        `)
        .eq('user_id', userId)
        .maybeSingle();

      if (memberError) throw memberError;

      const clubData = memberData?.clubs
        ? {
            ...memberData.clubs,
            role: memberData.role
          }
        : null;

      setMyClub(clubData);

      // all clubs
      const { data: clubsData, error: clubsError } = await supabase
        .from('clubs')
        .select(`
          *,
          club_members(count)
        `)
        .order('created_at', { ascending: false });

      if (clubsError) throw clubsError;

      const normalized =
        clubsData?.map((club: Record<string, unknown>) => ({
          ...club,
          member_count: club.club_members?.[0]?.count ?? 0
        })) || [];

      setAllClubs(normalized);
      } catch {
        console.error(error);
        toast.error('Không thể tham gia club');
      } finally {
        setJoining(false);
      }
    },
    [userId, joining, fetchClubData]
  );

  // =========================
  // LEAVE CLUB
  // =========================
  const leaveClub = useCallback(async () => {
    if (!userId) return;

    try {
      const { error } = await supabase
        .from('club_members')
        .delete()
        .eq('user_id', userId);

      if (error) throw error;

      setMyClub(null);
      toast.success('Đã rời câu lạc bộ');
      fetchClubData();
    } catch {
      toast.error('Không thể rời club');
    }
  }, [userId, fetchClubData]);

  // =========================
  // INITIAL LOAD + REALTIME
  // =========================
  useEffect(() => {
    if (!userId) return;

    fetchClubData();

    const channel = supabase
      .channel(`clubs-${userId}`)
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'club_members'
        },
        () => {
          fetchClubData();
        }
      )
      .on(
        'postgres_changes',
        {
          event: '*',
          schema: 'public',
          table: 'clubs'
        },
        () => {
          fetchClubData();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [userId, fetchClubData]);

  return {
    myClub,
    allClubs,
    loading,
    joining,
    joinClub,
    leaveClub,
    refresh: fetchClubData
  };
}

import { useState, useCallback } from 'react';
import { toast } from 'sonner';
import { supabase } from '../lib/supabase';

interface UsePostActionsProps {
  currentUserId: string | undefined;
}

export function usePostActions({ currentUserId }: UsePostActionsProps) {
  const [savedPosts, setSavedPosts] = useState<Set<string>>(new Set());
  const [cheeredPosts, setCheeredPosts] = useState<Set<string>>(new Set());

  const toggleSavePost = useCallback(async (postId: string) => {
    if (!currentUserId) return false;

    const isSaved = savedPosts.has(postId);
    const newState = !isSaved;

    setSavedPosts(prev => {
      const next = new Set(prev);
      if (newState) next.add(postId);
      else next.delete(postId);
      return next;
    });

    try {
      if (newState) {
        const { error } = await supabase.from('saved_posts').insert({ user_id: currentUserId, post_id: postId });
        if (error) throw error;
        toast.success('Đã lưu bài viết vào mục Lưu trữ', { icon: '🔖' });
      } else {
        const { error } = await supabase.from('saved_posts').delete().eq('user_id', currentUserId).eq('post_id', postId);
        if (error) throw error;
        toast.info('Đã bỏ lưu bài viết');
      }
      return true;
    } catch {
      setSavedPosts(prev => {
        const next = new Set(prev);
        if (isSaved) next.add(postId);
        else next.delete(postId);
        return next;
      });
      toast.error('Có lỗi xảy ra, vui lòng thử lại sau.');
      return false;
    }
  }, [currentUserId, savedPosts]);

  const cheersPost = useCallback(async (post: { id: string; author_id: string }) => {
    if (!currentUserId || !post.id) {
      toast.error("Lỗi dữ liệu: Bài viết này không có ID!");
      return false;
    }

    if (cheeredPosts.has(post.id)) {
      toast.error('Bạn đã cụng ly bài này rồi!');
      return false;
    }

    setCheeredPosts(prev => new Set(prev).add(post.id));
    const now = new Date();
    const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    const tid = toast.loading('Đang cụng ly... 🍻', { icon: '💦' });

    try {
      const { data, error } = await supabase.rpc('action_cheers_post', {
        p_post_id: String(post.id),
        p_author_id: post.author_id ? String(post.author_id) : '00000000-0000-0000-0000-000000000000',
        p_local_date: today,
      });

      if (error) throw error;

      if (data === true) {
        toast.success('+200ml vào mục tiêu hôm nay!', { id: tid, icon: '✨' });
        await supabase.rpc('pulse_post', { p_post_id: String(post.id) });
        return true;
      } else {
        toast.error('Bạn đã cụng ly bài này rồi!', { id: tid });
        setCheeredPosts(prev => {
          const next = new Set(prev);
          next.delete(post.id);
          return next;
        });
        return false;
      }
    } catch {
      setCheeredPosts(prev => {
        const next = new Set(prev);
        next.delete(post.id);
        return next;
      });
      toast.error('Lỗi máy chủ, chưa thể cộng nước!', { id: tid, icon: '💦' });
      return false;
    }
  }, [currentUserId, cheeredPosts]);

  const deletePost = useCallback(async (postId: string) => {
    const { confirmDialog } = await import('@/store/useConfirmDialog');
    const ok = await confirmDialog({ title: 'Xóa bài viết', message: 'Bạn có chắc chắn muốn xóa bài viết này?', confirmLabel: 'Xóa', variant: 'danger' });
    if (!ok) return false;

    const tid = toast.loading('Đang xóa bài viết...');
    try {
      const { error } = await supabase
        .from('social_posts')
        .delete()
        .eq('id', postId)
        .eq('author_id', currentUserId);
      if (error) throw error;
      toast.success('Đã xóa bài viết thành công', { id: tid });
      return true;
    } catch (err: unknown) {
      console.error("Lỗi xóa bài viết:", err);
      toast.error('Không thể xóa bài viết lúc này!', { id: tid });
      return false;
    }
  }, []);

  const reportPost = useCallback(async (postId: string) => {
    const { confirmDialog } = await import('@/store/useConfirmDialog');
    const ok = await confirmDialog({ title: 'Báo cáo bài viết', message: 'Báo cáo bài viết này vì chứa nội dung spam hoặc không phù hợp?', confirmLabel: 'Báo cáo', variant: 'danger' });
    if (!ok) return false;

    const tid = toast.loading('Đang gửi báo cáo đến hệ thống...');
    try {
      const { error } = await supabase.from('reports').insert({ target_id: postId, target_type: 'post', reporter_id: currentUserId, reason: 'Inappropriate content / Spam' });
      if (error) throw error;
      toast.success('Đã ghi nhận báo cáo. Bài viết đã được ẩn khỏi Feed của bạn.', { id: tid });
      return true;
    } catch (err) {
      console.warn('Report error:', err);
      toast.error('Gửi báo cáo thất bại, vui lòng thử lại sau.', { id: tid });
      return false;
    }
  }, [currentUserId]);

  const editPost = useCallback(async (postId: string, currentContent: string) => {
    const newContent = window.prompt('Chỉnh sửa bài viết:', currentContent);
    if (newContent !== null && newContent.trim() !== currentContent) {
      const tid = toast.loading('Đang cập nhật...');
      try {
        const { error } = await supabase
          .from('social_posts')
          .update({ content: newContent.trim() })
          .eq('id', postId)
          .eq('author_id', currentUserId);
        if (error) throw error;
        toast.success('Đã cập nhật bài viết', { id: tid });
        return newContent.trim();
      } catch {
        toast.error('Lỗi khi cập nhật!', { id: tid });
        return null;
      }
    }
    return null;
  }, []);

  const joinChallenge = useCallback(async (opponentId: string) => {
    if (!currentUserId || !opponentId) {
      toast.error("Vui lòng đăng nhập để thách đấu!");
      return false;
    }

    if (currentUserId === opponentId) {
      toast.error("Sếp không thể tự thách đấu chính mình!");
      return false;
    }

    const tid = toast.loading('Đang gửi chiến thư...');
    try {
      const { error } = await supabase.from('hydration_battles').insert({ challenger_id: currentUserId, opponent_id: opponentId, stake_coins: 0, status: 'pending' });
      if (error) throw error;
      toast.success('Đã gửi chiến thư! Đối thủ sẽ nhận được thông báo trong Đấu trường. ⚔️', { id: tid });
      return true;
    } catch (err: unknown) {
      console.error("Lỗi gửi chiến thư:", err);
      toast.error('Không thể gửi chiến thư lúc này!', { id: tid });
      return false;
    }
  }, [currentUserId]);

  return {
    savedPosts,
    cheeredPosts,
    toggleSavePost,
    cheersPost,
    deletePost,
    reportPost,
    editPost,
    joinChallenge,
  };
}

import { useMemo } from 'react';
import type { HydrationSchedule } from '../lib/HydrationEngine';
import type { CalendarEventItem } from './useCalendarSync';

/**
 * Parse time string "HH:MM" to minutes since midnight
 */
function timeToMinutes(time: string): number | null {
  const [h, m] = time.split(':').map(Number);
  if (!Number.isFinite(h) || !Number.isFinite(m)) return null;
  return h * 60 + m;
}

/**
 * Format minutes since midnight back to "HH:MM"
 */
function minutesToTime(minutes: number): string {
  const normalized = Math.max(0, Math.min(23 * 60 + 59, minutes));
  const h = Math.floor(normalized / 60) % 24;
  const m = Math.round(normalized % 60);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

type EventCategory = 'SPORT' | 'DEEP_WORK' | 'SOCIAL' | 'NORMAL';

type BusyWindow = {
  start: number;
  end: number;
  event: CalendarEventItem;
  category: EventCategory;
};

const PRE_EVENT_BUFFER_MINUTES = 10;
const POST_EVENT_BUFFER_MINUTES = 20;
const MIN_DRINK_SPACING_MINUTES = 25;
const EARLIEST_DRINK_MINUTES = 6 * 60;
const LATEST_DRINK_MINUTES = 23 * 60;
const SEARCH_WINDOW_MINUTES = 120;

function detectCategory(title: string): EventCategory {
  const t = title.toLowerCase();
  const sportKeywords = ['gym', 'tập', 'bóng đá', 'cầu lông', 'chạy', 'yoga', 'bơi', 'workout', 'sport', 'dance', 'tennis', 'đá banh'];
  const deepWorkKeywords = ['học', 'họp', 'thi', 'biên dịch', 'nghiên cứu', 'meeting', 'class', 'lecture', 'study', 'tiết'];
  const socialKeywords = ['cafe', 'tiệc', 'party', 'hẹn', 'đi chơi', 'shopping', 'date'];

  if (sportKeywords.some(kw => t.includes(kw))) return 'SPORT';
  if (deepWorkKeywords.some(kw => t.includes(kw))) return 'DEEP_WORK';
  if (socialKeywords.some(kw => t.includes(kw))) return 'SOCIAL';
  return 'NORMAL';
}

function buildBusyWindows(events: CalendarEventItem[]): BusyWindow[] {
  return events
    .filter(event => !event.isAllDay)
    .map((event) => {
      const startMinutes = timeToMinutes(event.start);
      const rawEndMinutes = timeToMinutes(event.end);

      if (startMinutes === null || rawEndMinutes === null) return null;

      const endMinutes = rawEndMinutes <= startMinutes ? 24 * 60 : rawEndMinutes;
      const category = detectCategory(event.title);

      return {
        start: Math.max(0, startMinutes - PRE_EVENT_BUFFER_MINUTES),
        end: Math.min(24 * 60, endMinutes + POST_EVENT_BUFFER_MINUTES),
        event,
        category,
      };
    })
    .filter((window): window is BusyWindow => !!window)
    .sort((a, b) => a.start - b.start);
}

function findOverlappingWindow(
  timeMinutes: number,
  busyWindows: BusyWindow[],
): BusyWindow | null {
  for (const window of busyWindows) {
    if (timeMinutes >= window.start && timeMinutes < window.end) {
      return window;
    }
  }
  return null;
}

function isTooCloseToUsedSlot(timeMinutes: number, usedSlots: number[]) {
  return usedSlots.some(slot => Math.abs(slot - timeMinutes) < MIN_DRINK_SPACING_MINUTES);
}

/**
 * Find the nearest available slot before an event,
 * or after an event if before doesn't work.
 */
function findAvailableSlot(
  desiredMinutes: number,
  busyWindows: BusyWindow[],
  usedSlots: number[],
): number {
  for (let offset = 0; offset <= SEARCH_WINDOW_MINUTES; offset += 15) {
    const candidates = offset === 0
      ? [desiredMinutes]
      : [desiredMinutes - offset, desiredMinutes + offset];

    for (const candidate of candidates) {
      if (candidate < EARLIEST_DRINK_MINUTES || candidate > LATEST_DRINK_MINUTES) continue;
      if (findOverlappingWindow(candidate, busyWindows)) continue;
      if (isTooCloseToUsedSlot(candidate, usedSlots)) continue;
      return candidate;
    }
  }

  // Keep original time but mark as busy
  return desiredMinutes;
}

export interface SmartScheduleItem {
  time: string;
  amount: number;
  note: string;
  isAdjusted: boolean;
  conflictingEvent?: string;
}

export function useSmartSchedule(
  baseSchedule: HydrationSchedule[] | null,
  calendarEvents: CalendarEventItem[],
  waterGoal: number,
): {
  schedule: SmartScheduleItem[];
  busyEventCount: number;
  totalAdjustedCount: number;
  hasEventsToday: boolean;
} {
  return useMemo(() => {
    if (!baseSchedule || baseSchedule.length === 0) {
      return {
        schedule: [],
        busyEventCount: 0,
        totalAdjustedCount: 0,
        hasEventsToday: calendarEvents.length > 0,
      };
    }

    let adjustedCount = 0;
    const busyWindows = buildBusyWindows(calendarEvents);
    const usedSlots: number[] = [];

    const smartSchedule: SmartScheduleItem[] = baseSchedule.map((item) => {
      const originalMinutes = timeToMinutes(item.time);
      if (originalMinutes === null) {
        return {
          time: item.time,
          amount: item.amount,
          note: item.note || 'Uống nước',
          isAdjusted: false,
        };
      }

      const overlapping = findOverlappingWindow(originalMinutes, busyWindows);

      if (!overlapping) {
        usedSlots.push(originalMinutes);
        return {
          time: item.time,
          amount: item.amount,
          note: item.note || 'Uống nước',
          isAdjusted: false,
        };
      }

      // Find best alternative slot
      const newMinutes = findAvailableSlot(originalMinutes, busyWindows, usedSlots);
      const isActuallyMoved = newMinutes !== originalMinutes;
      if (isActuallyMoved) adjustedCount++;
      usedSlots.push(newMinutes);

      // Adjust amount based on category
      let finalAmount = item.amount;
      let categoryNote = '';
      if (overlapping.category === 'SPORT') {
        finalAmount += 150;
        categoryNote = ' (+150ml bù thể thao)';
      } else if (overlapping.category === 'DEEP_WORK') {
        categoryNote = ' (ưu tiên tỉnh táo)';
      }

      return {
        time: minutesToTime(newMinutes),
        amount: finalAmount,
        note: isActuallyMoved
          ? `Né "${overlapping.event.title}"${categoryNote} - ${item.note || 'uống nước'}`
          : `Trùng "${overlapping.event.title}"${categoryNote} - uống nhanh ${finalAmount}ml`,
        isAdjusted: true,
        conflictingEvent: overlapping.event.title,
      };
    });

    return {
      schedule: smartSchedule.sort((a, b) => a.time.localeCompare(b.time)),
      busyEventCount: busyWindows.length,
      totalAdjustedCount: adjustedCount,
      hasEventsToday: calendarEvents.length > 0,
    };
  }, [baseSchedule, calendarEvents, waterGoal]);
}

import React, { useState, useEffect, useMemo, useRef, useCallback } from 'react';
import { toast } from 'sonner';
import { supabase } from '../lib/supabase';
import { useUIStore } from '../store/useUIStore';
import {
  buildProgressShareText,
  DEFAULT_SOCIAL_COMPOSER,
  DEFAULT_SOCIAL_PROFILE_STATS,
  isMissingSocialSchemaError,
  type SocialComposerState,
  type CloseCircleMember,
  type SocialDiscoverProfile,
  type SocialFeedPost,
  type SocialProfileStats,
} from '../lib/social';

interface UseSocialDataProps {
  profile: Record<string, unknown> | null;

  tab: string;
  setActiveTab: (tab: string) => void;
}

export function useSocialData({ profile, waterIntake, waterGoal, streak, activeTab, setActiveTab }: UseSocialDataProps) {
  const [showSocialComposer, setShowSocialComposer] = useState(false);
  const [showDiscoverPeople, setShowDiscoverPeople] = useState(false);
  const [showSocialProfile, setShowSocialProfile] = useState(false);
  const [socialComposer, setSocialComposer] = useState<SocialComposerState>({ ...DEFAULT_SOCIAL_COMPOSER });
  const [socialPosts, setSocialPosts] = useState<SocialFeedPost[]>([]);
  const [socialStories, setSocialStories] = useState<SocialFeedPost[]>([]);
  const [socialSearchQuery, setSocialSearchQuery] = useState('');
  const [socialSearchResults, setSocialSearchResults] = useState<SocialDiscoverProfile[]>([]);
  const [socialFollowingIds, setSocialFollowingIds] = useState<string[]>([]);
  const [closeCircleMembers, setCloseCircleMembers] = useState<CloseCircleMember[]>([]);
  const [isCloseCircleLoading, setIsCloseCircleLoading] = useState(false);
  const [socialProfileStats, setSocialProfileStats] = useState<SocialProfileStats>(DEFAULT_SOCIAL_PROFILE_STATS);
  const [socialError, setSocialError] = useState('');
  const [isSocialLoading, setIsSocialLoading] = useState(false);
  const [isPublishingSocialPost, setIsPublishingSocialPost] = useState(false);
  const [isSocialSearching, setIsSocialSearching] = useState(false);
  const [socialImageFile, setSocialImageFile] = useState<File | null>(null);
  const [socialImagePreview, setSocialImagePreview] = useState('');
  const socialImageInputRef = useRef<HTMLInputElement>(null);
  const [showQuickDropCamera, setShowQuickDropCamera] = useState(false);
  const [isPublishingQuickDrop, setIsPublishingQuickDrop] = useState(false);

  useEffect(() => {
    if (!profile?.id) {
      setShowSocialComposer(false);
      setShowQuickDropCamera(false);
      setShowDiscoverPeople(false);
      setShowSocialProfile(false);
      setSocialPosts([]);
      setSocialStories([]);
      setSocialSearchResults([]);
      setSocialFollowingIds([]);
      setCloseCircleMembers([]);
      setSocialProfileStats(DEFAULT_SOCIAL_PROFILE_STATS);
      setSocialError('');
      resetSocialComposer();
    }
  }, [profile?.id]);

  useEffect(() => {
    if (activeTab === 'feed' && profile?.id) {
      void refreshSocialFeed();
    }
  }, [activeTab, profile?.id]);

  useEffect(() => {
    if (showDiscoverPeople && profile?.id) {
      void loadSocialDirectory(socialSearchQuery);
    }
  }, [showDiscoverPeople, profile?.id]);

  useEffect(() => () => {
    if (socialImagePreview.startsWith('blob:')) {
      URL.revokeObjectURL(socialImagePreview);
    }
  }, [socialImagePreview]);

  const getSocialErrorMessage = (message?: string) => {
    if (!message) return 'Không thể tải tính năng cộng đồng lúc này.';
    if (isMissingSocialSchemaError(message)) {
      return 'Social chưa được bật trên Supabase. Hãy chạy file supabase/social_lite.sql rồi mở lại app.';
    }
    return message;
  };

  const closeCircleIds = useMemo(() => closeCircleMembers.map(member => member.id), [closeCircleMembers]);

  const resetSocialComposer = useCallback(() => {
    if (socialImagePreview.startsWith('blob:')) {
      URL.revokeObjectURL(socialImagePreview);
    }
    setSocialComposer({ ...DEFAULT_SOCIAL_COMPOSER });
    setSocialImageFile(null);
    setSocialImagePreview('');
  }, [socialImagePreview]);

  const closeSocialComposer = () => {
    resetSocialComposer();
    setShowSocialComposer(false);
    useUIStore.getState().setShowSocialComposer(false);
  };

  const loadCloseCircle = async (options?: { silent?: boolean }): Promise<CloseCircleMember[]> => {
    if (!profile?.id) return [];

    if (!options?.silent) setIsCloseCircleLoading(true);
    try {
      const { data: rows, error } = await supabase!
        .from('social_follows')
        .select('following_id, created_at')
        .eq('follower_id', profile.id)
        .order('created_at', { ascending: false });
      if (error) throw error;

      const partnerRows = rows || [];
      const partnerIds = partnerRows.map((row: { following_id: string }) => row.following_id).filter(Boolean);
      if (partnerIds.length === 0) {
        setCloseCircleMembers([]);
        setSocialFollowingIds([]);
        return [];
      }

      const { data: profiles, error: profilesError } = await supabase!
        .from('public_profiles')
        .select('id, nickname, avatar_url, level, water_today, water_goal')
        .in('id', partnerIds);
      if (profilesError) throw profilesError;
      const profileMap = new Map((profiles || []).map((row: { id: string; nickname: string; avatar_url?: string | null; level: number | null; water_today: number | null; water_goal: number | null }) => [row.id, row]));

      const members = partnerRows.map((row: { following_id: string; priority?: number }, index: number) => {
        const partner = profileMap.get(row.following_id) || {};
        return {
          id: row.following_id,
          nickname: partner.nickname || 'Bạn DigiWell',
          avatar_url: partner.avatar_url ?? null,
          level: partner.level ?? null,
          water_today: partner.water_today ?? null,
          water_goal: partner.water_goal ?? null,
          priority: row.priority ?? index + 1,
          is_pinned: false,
        } satisfies CloseCircleMember;
      });

      setCloseCircleMembers(members);
      setSocialFollowingIds(members.map(member => member.id));
      return members;
    } catch (err: unknown) {
      const friendlyMessage = getSocialErrorMessage(err instanceof Error ? err.message : String(err));
      setSocialError(friendlyMessage);
      if (!options?.silent) toast.error(friendlyMessage);
      return [];
    } finally {
      setIsCloseCircleLoading(false);
    }
  };

  const openSocialComposer = (kind: SocialComposerState['postKind'] = 'status') => {
    if (!profile?.id) {
      toast.error('Vui lòng đăng nhập lại để đăng bài.');
      return;
    }

    if (kind === 'story') {
      setActiveTab('feed');
      setShowQuickDropCamera(true);
      return;
    }

    const content = kind === 'progress'
      ? buildProgressShareText({
        nickname: profile.nickname,
        waterIntake,
        waterGoal,
        streak,
      })
      : '';

    resetSocialComposer();
    setSocialComposer({
      content,
      imageUrl: '',
      postKind: kind === 'progress' ? 'status' : kind,
      visibility: 'followers',
    });
    setActiveTab('feed');
    setShowSocialComposer(true);
    useUIStore.getState().setShowSocialComposer(true);
  };

  const uploadSocialImage = async (file: File) => {
    if (!profile?.id) throw new Error('Vui lòng đăng nhập lại.');

    const extension = file.name.includes('.') ? file.name.split('.').pop()?.toLowerCase() : 'jpg';
    const safeExtension = extension || 'jpg';
    const filePath = `${profile.id}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${safeExtension}`;
    const { error } = await supabase!.storage.from('social-media').upload(filePath, file, {
      cacheControl: '3600',
      upsert: false,
      contentType: file.type || undefined,
    });
    if (error) throw error;
    return supabase!.storage.from('social-media').getPublicUrl(filePath).data.publicUrl;
  };

  const loadSocialDirectory = async (query: string) => {
    if (!profile?.id) return;

    setIsSocialSearching(true);
    try {
      const keyword = query.trim();
      let request = supabase!
        .from('public_profiles')
        .select('id, nickname, avatar_url, level, water_today, water_goal')
        .neq('id', profile.id);

      if (keyword) {
        request = request.filter('nickname', 'ilike', `%${keyword}%`);
      } else {
        request = request.order('nickname', { ascending: true });
      }

      const { data, error } = await request.limit(8);
      if (error) throw error;

      const circleSet = new Set(closeCircleIds);
      setSocialError('');
      setSocialSearchResults((data || []).map((user: { id: string; nickname: string; avatar_url?: string | null; level?: number | null; water_today?: number | null; water_goal?: number | null }, index: number) => ({
        id: user.id || `search-user-fallback-${index}`,
        nickname: user.nickname || 'Người dùng DigiWell',
        isFollowing: socialFollowingIds.includes(user.id),
        isInCircle: circleSet.has(user.id),
        avatar_url: user.avatar_url ?? null,
        level: user.level ?? null,
        water_today: user.water_today ?? null,
        water_goal: user.water_goal ?? null,
      })));
    } catch (err: unknown) {
      const friendlyMessage = getSocialErrorMessage(err instanceof Error ? err.message : String(err));
      setSocialError(friendlyMessage);
      toast.error(friendlyMessage);
    } finally {
      setIsSocialSearching(false);
    }
  };

  const refreshSocialFeed = async (options?: { silent?: boolean }) => {
    if (!profile?.id) return;

    if (!options?.silent) {
      setIsSocialLoading(true);
    }

    try {
      const circleMembers = await loadCloseCircle({ silent: true });
      const circleIds = circleMembers.map(member => member.id);

      const [
        followingRes,
        profileStatsRes,
      ] = await Promise.all([
        supabase!.from('social_follows').select('following_id').eq('follower_id', profile.id),
        supabase!.rpc('get_profile_stats', { p_user_id: profile.id })
      ]);

      if (followingRes.error) throw followingRes.error;
      if (profileStatsRes.error) throw profileStatsRes.error;

      const stats = profileStatsRes.data || { follower_count: 0, following_count: 0, post_count: 0 };
      const followingIds = circleIds;
      setSocialFollowingIds(followingIds);
      setSocialProfileStats({
        followers: stats.follower_count,
        following: stats.following_count,
        posts: stats.post_count,
      });

      const feedAuthorIds = Array.from(new Set([profile.id, ...followingIds]));
      const { data: postRows, error: postsError } = await supabase!
        .from('social_posts')
        .select('id, author_id, content, image_url, post_kind, visibility, hydration_ml, streak_snapshot, like_count, created_at, expires_at')
        .in('author_id', feedAuthorIds)
        .order('created_at', { ascending: false })
        .range(0, 19);

      if (postsError) throw postsError;

      const validRows = (postRows || []).filter((row: { post_kind: string; expires_at: string | null }) => {
        if (row.post_kind !== 'story') return true;
        if (!row.expires_at) return false;
        return new Date(row.expires_at).getTime() > Date.now();
      });

      const authorIds = Array.from(new Set(validRows.map((row: { author_id: string }) => row.author_id)));
      const postIds = validRows.map((row: { id: string }) => row.id);

      const [profilesRes, likesRes] = await Promise.all([
        authorIds.length > 0
          ? supabase!.from('public_profiles').select('id, nickname, avatar_url, level, water_today, water_goal').in('id', authorIds)
          : Promise.resolve({ data: [], error: null }),
        postIds.length > 0
          ? supabase!.from('post_cheers').select('post_id').eq('user_id', profile.id).in('post_id', postIds)
          : Promise.resolve({ data: [], error: null }),
      ]);

      if (profilesRes.error) throw profilesRes.error;
      if (likesRes.error) throw likesRes.error;

      const profileMap = new Map((profilesRes.data || []).map((row: { id: string; nickname: string; avatar_url?: string | null; level?: number | null; water_today?: number | null; water_goal?: number | null }) => [row.id, {
        id: row.id,
        nickname: row.nickname || 'Người dùng DigiWell',
        avatar_url: row.avatar_url ?? null,
        level: row.level ?? null,
        water_today: row.water_today ?? null,
        water_goal: row.water_goal ?? null,
      }]));
      const likedPostIds = new Set((likesRes.data || []).map((row: { post_id: string }) => row.post_id));

      const mappedPosts: SocialFeedPost[] = validRows.map((row: Record<string, unknown>, index: number) => ({
        ...row,
        id: row.id || `post-fallback-${index}`,
        author: profileMap.get(row.author_id) || {
          id: row.author_id,
          nickname: row.author_id === profile.id ? (profile.nickname || 'Bạn') : 'Người dùng DigiWell',
        },
        likedByMe: likedPostIds.has(row.id),
      }));

      const storyMap = new Map<string, SocialFeedPost>();
      const latestStories = mappedPosts
        .filter(post => post.post_kind === 'story')
        .reduce<SocialFeedPost[]>((acc: SocialFeedPost[], post: SocialFeedPost) => {
          if (storyMap.has(post.author_id)) return acc;
          storyMap.set(post.author_id, post);
          acc.push(post);
          return acc;
        }, []);

      setSocialStories(latestStories);
      setSocialPosts(mappedPosts.filter(post => post.post_kind !== 'story'));
      setSocialError('');
    } catch (err: unknown) {
      const friendlyMessage = getSocialErrorMessage(err instanceof Error ? err.message : String(err));
      setSocialError(friendlyMessage);
      setSocialPosts([]);
      setSocialStories([]);
      if (!options?.silent) {
        toast.error(friendlyMessage);
      }
    } finally {
      setIsSocialLoading(false);
    }
  };

  const handleSocialImagePicked = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error('Chỉ hỗ trợ ảnh JPG, PNG, WEBP hoặc HEIC.');
      event.target.value = '';
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      toast.error('Ảnh tối đa 5MB để upload nhanh hơn.');
      event.target.value = '';
      return;
    }

    if (socialImagePreview.startsWith('blob:')) {
      URL.revokeObjectURL(socialImagePreview);
    }

    const previewUrl = URL.createObjectURL(file);
    setSocialImageFile(file);
    setSocialImagePreview(previewUrl);
    setSocialComposer((prev: SocialComposerState) => ({ ...prev, imageUrl: '' }));
    event.target.value = '';
  };

  const openQuickDropCamera = () => {
    if (!profile?.id) {
      toast.error('Vui lòng đăng nhập lại để đăng Drop.');
      return;
    }

    setActiveTab('feed');
    setShowQuickDropCamera(true);
  };

  const closeQuickDropCamera = () => {
    setShowQuickDropCamera(false);
  };

  const handleQuickDropCapture = async (blob: Blob) => {
    if (!profile?.id) {
      toast.error('Vui lòng đăng nhập lại để đăng Drop.');
      return;
    }

    const file = new File([blob], `drop-${Date.now()}.jpg`, { type: blob.type || 'image/jpeg' });
    setIsPublishingQuickDrop(true);
    const toastId = toast.loading('Đang đăng Drop...');
    try {
      const imageUrl = await uploadSocialImage(file);
      const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
      const { data, error } = await supabase!.from('social_posts').insert({
        author_id: profile.id,
        content: '',
        image_url: imageUrl,
        post_kind: 'story',
        visibility: 'followers',
        hydration_ml: waterIntake,
        streak_snapshot: streak,
        expires_at: expiresAt,
      }).select('id').single();
      if (error) throw error;
      if (!data?.id) throw new Error('Không nhận được Drop vừa tạo.');

      toast.success('Drop đã lên sóng.', { id: toastId });
      setShowQuickDropCamera(false);
      await refreshSocialFeed({ silent: true });
    } catch (err: unknown) {
      toast.error(getSocialErrorMessage(err instanceof Error ? err.message : String(err)), { id: toastId });
    } finally {
      setIsPublishingQuickDrop(false);
    }
  };

  const handleSearchSocialUsers = async (query: string) => {
    setSocialSearchQuery(query);
    await loadSocialDirectory(query);
  };

  const handleAddCircleMember = async (targetUserId: string, nickname: string) => {
    if (!profile?.id) return;
    if (targetUserId === profile.id) {
      toast.error('Không thể thêm chính bạn vào bạn bè.');
      return;
    }
    if (closeCircleIds.includes(targetUserId)) {
      toast.info(`${nickname} đã là bạn bè.`);
      return;
    }
    const toastId = toast.loading(`Đang thêm ${nickname} vào bạn bè...`);
    try {
      const { error } = await supabase!
        .from('social_follows')
        .upsert(
          { follower_id: profile.id, following_id: targetUserId },
          { onConflict: 'follower_id,following_id', ignoreDuplicates: true }
        );
      if (error) throw error;

      setSocialFollowingIds((prev: string[]) => prev.includes(targetUserId) ? prev : [...prev, targetUserId]);
      setSocialSearchResults((prev: SocialDiscoverProfile[]) => prev.map(user => user.id === targetUserId ? { ...user, isFollowing: true, isInCircle: true } : user));
      setSocialProfileStats((prev: SocialProfileStats) => ({ ...prev, following: prev.following + 1 }));
      toast.success(`Đã thêm ${nickname} vào bạn bè.`, { id: toastId });
      await loadCloseCircle({ silent: true });
      await refreshSocialFeed({ silent: true });
    } catch (err: unknown) {
      toast.error(getSocialErrorMessage(err instanceof Error ? err.message : String(err)), { id: toastId });
    }
  };

  const handleRemoveCircleMember = async (targetUserId: string, nickname: string) => {
    if (!profile?.id) return;

    const toastId = toast.loading(`Đang gỡ ${nickname} khỏi bạn bè...`);
    try {
      const { error } = await supabase!
        .from('social_follows')
        .delete()
        .eq('follower_id', profile.id)
        .eq('following_id', targetUserId);
      if (error) throw error;

      setSocialFollowingIds((prev: string[]) => prev.filter(id => id !== targetUserId));
      setSocialSearchResults((prev: SocialDiscoverProfile[]) => prev.map(user => user.id === targetUserId ? { ...user, isFollowing: false, isInCircle: false } : user));
      setSocialProfileStats((prev: SocialProfileStats) => ({ ...prev, following: Math.max(prev.following - 1, 0) }));
      toast.success(`Đã gỡ ${nickname} khỏi bạn bè.`, { id: toastId });
      await loadCloseCircle({ silent: true });
      await refreshSocialFeed({ silent: true });
    } catch (err: unknown) {
      toast.error(getSocialErrorMessage(err instanceof Error ? err.message : String(err)), { id: toastId });
    }
  };

  const handleFollowUser = handleAddCircleMember;
  const handleUnfollowUser = handleRemoveCircleMember;

  const handleToggleLikePost = async (post: SocialFeedPost) => {
    if (!profile?.id) return;

    const nextLiked = !post.likedByMe;
    const likeDelta = nextLiked ? 1 : -1;
    setSocialPosts((prev: SocialFeedPost[]) => prev.map(item => item.id === post.id ? {
      ...item,
      likedByMe: nextLiked,
      like_count: Math.max((item.like_count || 0) + likeDelta, 0),
    } : item));
    setSocialStories((prev: SocialFeedPost[]) => prev.map(item => item.id === post.id ? {
      ...item,
      likedByMe: nextLiked,
      like_count: Math.max((item.like_count || 0) + likeDelta, 0),
    } : item));

    try {
      if (nextLiked) {
        const { error } = await supabase!.from('social_post_likes').insert({
          post_id: post.id,
          user_id: profile.id,
        });
        if (error) throw error;
      } else {
        const { error } = await supabase!.from('social_post_likes')
          .delete()
          .eq('post_id', post.id)
          .eq('user_id', profile.id);
        if (error) throw error;
      }
    } catch (err: unknown) {
      setSocialPosts((prev: SocialFeedPost[]) => prev.map(item => item.id === post.id ? post : item));
      setSocialStories((prev: SocialFeedPost[]) => prev.map(item => item.id === post.id ? post : item));
      toast.error(getSocialErrorMessage(err instanceof Error ? err.message : String(err)));
    }
  };

  const handlePublishSocialPost = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!profile?.id) return;

    const trimmedContent = socialComposer.content.trim();
    const trimmedImageUrl = socialComposer.imageUrl.trim();

    if (socialComposer.postKind === 'story' && !trimmedImageUrl && !socialImageFile) {
      toast.error('Drop cần ảnh chụp nhanh trước khi đăng.');
      return;
    }

    if (socialComposer.postKind !== 'story' && !trimmedContent && !trimmedImageUrl && !socialImageFile) {
      toast.error('Viết gì đó hoặc thêm ảnh trước khi đăng.');
      return;
    }

    setIsPublishingSocialPost(true);
    const toastId = toast.loading(socialComposer.postKind === 'story' ? 'Đang đăng story...' : 'Đang đăng bài...');

    try {
      let imageUrl = trimmedImageUrl || null;
      if (socialImageFile) {
        imageUrl = await uploadSocialImage(socialImageFile);
      }

      const expiresAt = socialComposer.postKind === 'story'
        ? new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
        : null;

      const persistedPostKind = socialComposer.postKind === 'progress' ? 'status' : socialComposer.postKind;
      const { data, error } = await supabase!.from('social_posts').insert({
        author_id: profile.id,
        content: socialComposer.postKind === 'story' ? '' : trimmedContent,
        image_url: imageUrl,
        post_kind: persistedPostKind,
        visibility: socialComposer.visibility,
        hydration_ml: waterIntake,
        streak_snapshot: streak,
        expires_at: expiresAt,
      }).select('id').single();
      if (error) throw error;
      if (!data?.id) throw new Error('Không nhận được bài viết vừa tạo.');

      const successMessage = socialComposer.postKind === 'story'
        ? 'Drop đã lên sóng.'
        : socialComposer.postKind === 'challenge'
          ? 'Duel đã lên feed.'
          : 'Pulse đã xuất hiện trên feed.';
      toast.success(successMessage, { id: toastId });
      closeSocialComposer();
      await refreshSocialFeed({ silent: true });
    } catch (err: unknown) {
      toast.error(getSocialErrorMessage(err instanceof Error ? err.message : String(err)), { id: toastId });
    } finally {
      setIsPublishingSocialPost(false);
    }
  };

  return {
    showSocialComposer, setShowSocialComposer,
    showDiscoverPeople, setShowDiscoverPeople,
    showSocialProfile, setShowSocialProfile,
    socialComposer, setSocialComposer,
    socialPosts, setSocialPosts,
    socialStories, setSocialStories,
    socialSearchQuery, setSocialSearchQuery,
    socialSearchResults, setSocialSearchResults,
    socialFollowingIds, setSocialFollowingIds,
    closeCircleMembers, setCloseCircleMembers,
    closeCircleIds,
    isCloseCircleLoading,
    socialProfileStats, setSocialProfileStats,
    socialError, setSocialError,
    isSocialLoading, setIsSocialLoading,
    isPublishingSocialPost, setIsPublishingSocialPost,
    showQuickDropCamera, setShowQuickDropCamera,
    isPublishingQuickDrop,
    isSocialSearching, setIsSocialSearching,
    socialImageFile, setSocialImageFile,
    socialImagePreview, setSocialImagePreview,
    socialImageInputRef,
    closeSocialComposer,
    openSocialComposer,
    openQuickDropCamera,
    closeQuickDropCamera,
    loadCloseCircle,
    handleSocialImagePicked,
    handleQuickDropCapture,
    handleSearchSocialUsers,
    handleAddCircleMember,
    handleRemoveCircleMember,
    handleFollowUser,
    handleUnfollowUser,
    handleToggleLikePost,
    handlePublishSocialPost
  };
}

/* eslint-disable react-refresh/only-export-components */
import { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { supabase } from '@/lib/supabase';
import { toast } from 'sonner';
import { playWaterDropSound } from '@/lib/audio';
import type { Profile } from '@/models';
import { expGainedForWater } from '@/config/questConfig';
// @ts-expect-error: confetti module not installed
// import confetti from 'canvas-confetti';

// ── Dev-only logger ────────────────────────────────────────
const devLog = (...args: unknown[]) => {
  if (import.meta.env.DEV) {
    console.log('[useWaterData]', ...args);
  }
};
const devError = (...args: unknown[]) => {
  if (import.meta.env.DEV) {
    console.error('[useWaterData]', ...args);
  }
};

// ── Constants ──────────────────────────────────────────────

const OFFLINE_QUEUE_KEY = 'digiwell_offline_water_queue';

// ── Types ──────────────────────────────────────────────────

export interface WaterLog {
  id:         string;
  user_id:    string;
  amount:     number;
  name:       string;
  day:        string;
  exp:        number;
  created_at: string;
  timestamp:  string;
  factor:     number;
}

interface OfflineQueueItem {
  tempId:     string;
  user_id:    string;
  amount:     number;
  name:       string;
  exp:        number;
  day:        string;   // FIX: lưu ngay khi push, tránh sai ngày khi sync qua đêm
  created_at: string;
  factor:     number;
  tempC?:     number;
  exerciseMins?: number;
  isFasting?: boolean;
  logSynced?: boolean;
  progressionSynced?: boolean;
}

// ── Pure helpers ───────────────────────────────────────────

const isRealUser = (id: unknown): id is string =>
  typeof id === 'string' && id.length >= 30;

const toDateStr = (d = new Date()): string =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; // Local date
const normalizeRow = (row: Record<string, unknown>): WaterLog => {
  const createdAt = row.created_at ?? new Date().toISOString();
  return {
    id:         String(row.id ?? crypto.randomUUID()),
    user_id:    String(row.user_id ?? ''),
    amount:     Number(row.amount ?? 0),
    name:       row.name ?? 'Nuoc Loc',
    day:        row.day ?? toDateStr(new Date(createdAt)),
    exp:        Number(row.exp ?? 0),
    created_at: createdAt,
    timestamp:  row.timestamp ?? createdAt,
    factor:     Number(row.factor ?? 1),
  };
};

// ── Offline queue helpers ──────────────────────────────────

function getOfflineQueueKey(userId: string) {
  return `${OFFLINE_QUEUE_KEY}_${userId}`;
}

function readRawOfflineQueue(storageKey: string): OfflineQueueItem[] {
  try {
    return JSON.parse(localStorage.getItem(storageKey) ?? '[]');
  } catch {
    return [];
  }
}

function readScopedOfflineQueue(userId: string): OfflineQueueItem[] {
  return readRawOfflineQueue(getOfflineQueueKey(userId));
}

function writeOfflineQueue(userId: string, queue: OfflineQueueItem[]) {
  const scopedKey = getOfflineQueueKey(userId);

  if (queue.length > 0) {
    localStorage.setItem(scopedKey, JSON.stringify(queue));
  } else {
    localStorage.removeItem(scopedKey);
  }

  const legacyQueue = readRawOfflineQueue(OFFLINE_QUEUE_KEY);
  const remainingLegacyItems = legacyQueue.filter(item => item.user_id !== userId);
  if (remainingLegacyItems.length > 0) {
    localStorage.setItem(OFFLINE_QUEUE_KEY, JSON.stringify(remainingLegacyItems));
  } else {
    localStorage.removeItem(OFFLINE_QUEUE_KEY);
  }
}

function readOfflineQueue(userId: string): OfflineQueueItem[] {
  const scopedQueue = readScopedOfflineQueue(userId);
  const legacyQueue = readRawOfflineQueue(OFFLINE_QUEUE_KEY).filter(item => item.user_id === userId);
  return [...legacyQueue, ...scopedQueue];
}

function pushOfflineQueue(item: OfflineQueueItem) {
  const queue = readScopedOfflineQueue(item.user_id);
  queue.push(item);
  localStorage.setItem(getOfflineQueueKey(item.user_id), JSON.stringify(queue));
}

function updateOfflineQueueItem(userId: string, tempId: string, patch: Partial<OfflineQueueItem>) {
  const queue = readOfflineQueue(userId).map(item => (
    item.tempId === tempId ? { ...item, ...patch } : item
  ));
  writeOfflineQueue(userId, queue);
}

function removeOfflineQueueItem(userId: string, tempId: string) {
  const queue = readOfflineQueue(userId).filter(item => item.tempId !== tempId);
  writeOfflineQueue(userId, queue);
}

function clearOfflineQueue(userId: string) {
  writeOfflineQueue(userId, []);
}

// ── Hook ───────────────────────────────────────────────────

export function useWaterData(
  profile: (Profile & { water_today?: number }) | null,
  onWaterLogged?: (optimisticAmount?: number, optimisticExp?: number) => void | Promise<void>,
  envFactors: { tempC?: number; exerciseMins?: number; isFasting?: boolean } = {}
) {
  const [waterEntries,        setWaterEntries]        = useState<WaterLog[]>([]);
  const [isSyncing,           setIsSyncing]           = useState(false);
  const [hasPendingCloudSync, setHasPendingCloudSync] = useState(false);

  const mountedRef      = useRef(true);
  const waterIntakeRef  = useRef(0);
  const waterEntriesRef = useRef<WaterLog[]>([]);

  useEffect(() => () => { mountedRef.current = false; }, []);

  // FIX 1: Calculate from waterEntries with fallback to profile
  // Primary: sum of today's waterEntries
  // Fallback: profile.water_today if entries empty (fetch failed)
  const waterIntake = useMemo(() => {
    const fromEntries = waterEntries.reduce((sum, e) => sum + e.amount, 0);
    const fromProfile = profile?.water_today || 0;
    return fromEntries > 0 ? fromEntries : fromProfile;
  }, [waterEntries, profile?.water_today]);



  useEffect(() => {
    waterIntakeRef.current  = waterIntake;
    waterEntriesRef.current = waterEntries;
  }, [waterEntries, waterIntake]);

  useEffect(() => {
    if (!isRealUser(profile?.id)) {
      setTimeout(() => setHasPendingCloudSync(false), 0);
      return;
    }

    setTimeout(() => setHasPendingCloudSync(readOfflineQueue(profile.id).length > 0), 0);
  }, [profile?.id]);

  // ── Fetch ──────────────────────────────────────────────

  const fetchAllWater = useCallback(async () => {
    devLog('fetchAllWater called, profile.id:', profile?.id);
    if (!isRealUser(profile?.id)) {
      devLog('Not real user, skipping');
      return;
    }

    const today = toDateStr();
    devLog('Fetching water for today:', today);

    setIsSyncing(true);
    try {
      const { data, error } = await supabase
        .from('water_logs')
        .select('*')
        .eq('user_id', profile.id)
        .eq('day', today)  // Only today's entries
        .order('created_at', { ascending: false });

      if (error) {
        devError('fetchAllWater error:', error);
        throw error;
      }

      devLog('Fetched raw data:', data?.length || 0, 'records for today');
      const normalized = (data ?? []).map(normalizeRow);
      devLog('Normalized entries:', normalized.length, normalized.slice(0, 3).map((e: WaterLog) => ({ amount: e.amount, name: e.name })));

      setWaterEntries(normalized);
      devLog('Updated waterEntries state with', normalized.length, 'entries');
    } catch (err) {
      devError('fetchAllWater exception:', err);
      toast.error('Không thể tải nhật ký nước. Kiểm tra kết nối.');
      setWaterEntries([]);
    } finally {
      if (mountedRef.current) setIsSyncing(false);
    }
  }, [profile?.id]);

  // Auto fetch water data on mount/profile change
  useEffect(() => {
    if (profile?.id) {
      devLog('Profile changed, fetching water data');
      fetchAllWater();
    }
  }, [profile?.id, fetchAllWater]);

  // ── Listen to Smart Bottle Events for Optimistic UI ─────
  useEffect(() => {
    const handleSmartBottleEvent = (e: Event) => {
      const customEvent = e as CustomEvent;
      const detail = customEvent.detail;
      
      if (detail?.source === 'smart_bottle' && detail?.amount_ml > 0) {
        const now = detail.occurred_at || new Date().toISOString();
        const newEntry: WaterLog = {
          id: detail.log_id || `bottle-${Date.now()}`,
          user_id: profile?.id || '',
          amount: detail.amount_ml,
          name: 'DigiBottle',
          day: toDateStr(),
          exp: detail.added_exp || 0,
          created_at: now,
          timestamp: now,
          factor: 1,
        };
        
        setWaterEntries(prev => [newEntry, ...prev]);
      }
    };

    window.addEventListener('hydrationEvent', handleSmartBottleEvent);
    return () => {
      window.removeEventListener('hydrationEvent', handleSmartBottleEvent);
    };
  }, [profile?.id]);

  // ── Add water ──────────────────────────────────────────

  const handleAddWater = useCallback(
    async (amount: number, factor = 1, name = 'Nuoc Loc') => {
      if (!profile?.id) return;

      const actualAmount = Math.round(amount * factor);
      if (actualAmount <= 0) return;
      
      const { tempC, exerciseMins, isFasting } = envFactors;

      const exp    = expGainedForWater(actualAmount, profile.level || 1);
      const now    = new Date().toISOString();
      const today  = toDateStr();
      const tempId = `temp-${Date.now()}`;

      // 1. Optimistic UI
      const optimisticEntry: WaterLog = {
        id: tempId, user_id: String(profile.id),
        amount: actualAmount, name, day: today,
        exp, created_at: now, timestamp: now, factor,
      };
      setWaterEntries(prev => [optimisticEntry, ...prev]);
      playWaterDropSound();

      // 2. Demo mode
      if (!isRealUser(profile.id)) {
        toast.success(`Đã ghi nhận +${actualAmount}ml.`);
        return;
      }

      try {
        const { data, error } = await supabase
          .from('water_logs')
          .insert({ user_id: profile.id, amount: actualAmount, name, exp, day: today })
          .select('id')
          .single();

        if (error) throw error;

        // [QUAN TRỌNG] Gọi RPC để backend tự cộng EXP, Level và Coin an toàn tuyệt đối
        const rpcRes = await supabase.rpc('process_hydration_event', {
          p_user_id: profile.id,
          p_amount_ml: actualAmount,
          p_temp_c: tempC || null,
          p_exercise_mins: exerciseMins || 0,
          p_is_fasting: isFasting || false
        });
        if (rpcRes.error) {
          devError('RPC process_hydration_event error:', rpcRes.error);
        }

        // Swap tempId -> real ID, không cần refetch toàn bộ
        setWaterEntries(prev =>
          prev.map(e => e.id === tempId ? { ...e, id: String(data.id) } : e),
        );

        toast.success(`Đã ghi nhận +${actualAmount}ml.`);

        // Confetti (milestones only) handled elsewhere to keep routine logs calm.

        // [FIX] Truyền actualAmount và exp để handleWaterSync cập nhật profile
        // (coins, EXP, level, water_today) ngay lập tức thay vì chờ refetch DB
        await onWaterLogged?.(actualAmount, exp);

        // Clubs sync: fire & forget, không block UI
        syncToClubs(profile.id, actualAmount).catch(devError);

      } catch (err) {
        devError('addWater:', err);
        toast.error('Không thể ghi nhận lúc này. Đã lưu offline để đồng bộ sau.');

        // Rollback optimistic entry
        setWaterEntries(prev => prev.filter(e => e.id !== tempId));

        // Lưu day ngay tại đây thay vì tính lại khi sync
        pushOfflineQueue({
          tempId, user_id: String(profile.id),
          amount: actualAmount, name, exp,
          day: today,
          created_at: now, factor,
          tempC, exerciseMins, isFasting
        });

        setHasPendingCloudSync(true);
      }
    },
    [profile?.id, onWaterLogged],
  );

  // ── Delete ─────────────────────────────────────────────

  const _doDelete = useCallback(
    async (id: string, entry: WaterLog) => {
      const snapshot = waterEntriesRef.current;
      setWaterEntries(prev => prev.filter(e => e.id !== id));

      if (id.startsWith('temp') || !isRealUser(profile?.id)) {
        toast.success('Đã xóa.');
        return;
      }

      try {
        devLog('Deleting entry from DB:', id);
        const { error } = await supabase
          .from('water_logs')
          .delete()
          .eq('id', id)
          .eq('user_id', profile.id);
        if (error) {
          devError('Delete error:', error);
          throw error;
        }

        devLog('Delete successful, notifying parent');
        // Notify với số âm để parent trừ đúng delta
        await onWaterLogged?.(-entry.amount, -entry.exp);

        // Force refetch to ensure data consistency
        setTimeout(() => fetchAllWater(), 500);

        toast.success('Đã xóa.');
      } catch (err) {
        devError('Delete failed:', err);
        setWaterEntries(snapshot);
        toast.error('Không thể xóa. Thử lại sau.');
      }
    },
    [profile?.id, onWaterLogged, fetchAllWater],
  );

  const handleDeleteEntry = useCallback(
    async (rawId: unknown) => {
      const id = String(rawId ?? '');
      if (!id) return;

      const entry = waterEntriesRef.current.find(e => e.id === id);
      if (!entry) return;

      toast(`Xóa ${entry.amount}ml ${entry.name}?`, {
        action:   { label: 'Xác nhận', onClick: () => _doDelete(id, entry) },
        cancel:   { label: 'Hủy',      onClick: () => {} },
        duration: 5000,
      });
    },
    [_doDelete],
  );

  // ── Edit ───────────────────────────────────────────────

  const handleEditEntry = useCallback(async (id: string, newAmount: number) => {
    const originalEntry = waterEntriesRef.current.find(e => e.id === id);
    if (!originalEntry) {
      toast.error('Lỗi: Không tìm thấy mục cần sửa.');
      return;
    }

    if (Number.isNaN(newAmount) || newAmount <= 0) {
      toast.error('Lượng nước không hợp lệ.');
      return;
    }

    const newExp      = expGainedForWater(newAmount, profile?.level || 1);
    const snapshot = waterEntriesRef.current;
    // Tính delta để notify parent đúng số chênh lệch, không phải tổng mới
    const deltaAmount = newAmount - originalEntry.amount;
    const deltaExp    = newExp    - originalEntry.exp;

    setWaterEntries(prev =>
      prev.map(e => e.id === id ? { ...e, amount: newAmount, exp: newExp } : e),
    );

    if (!isRealUser(profile?.id) || id.startsWith('temp-')) return;

    try {
      const { error } = await supabase
        .from('water_logs')
        .update({ amount: newAmount, exp: newExp })
        .eq('id', id)
        .eq('user_id', profile.id);

      if (error) throw error;

      toast.success('Đã cập nhật lượng nước!');
      if (deltaAmount !== 0) await onWaterLogged?.(deltaAmount, deltaExp);
    } catch (err) {
      devError('edit failed:', err);
      setWaterEntries(snapshot);
      toast.error('Không thể cập nhật. Kiểm tra kết nối.');
    }
  }, [profile?.id, onWaterLogged]);

  // ── Offline sync ───────────────────────────────────────

  const syncOfflineLogs = useCallback(async () => {
    if (!isRealUser(profile?.id)) return;

    const queue = readOfflineQueue(profile.id);
    if (!queue.length) return;

    devLog('Syncing offline queue:', queue.length, 'items');

    try {
      let syncedCount = 0;

      for (const item of queue) {
        if (!item.logSynced) {
          const { data: existingLog, error: existingLogError } = await supabase
            .from('water_logs')
            .select('id')
            .eq('user_id', item.user_id)
            .eq('day', item.day)
            .eq('amount', item.amount)
            .eq('name', item.name)
            .eq('created_at', item.created_at)
            .maybeSingle();

          if (existingLogError) {
            devError('Existing log lookup error:', existingLogError);
            throw existingLogError;
          }

          if (!existingLog) {
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            const { tempId: _t, factor: _f, tempC: _tc, exerciseMins: _em, isFasting: _if, logSynced: _ls, progressionSynced: _ps, ...payload } = item;
            const { error: insertError } = await supabase.from('water_logs').insert(payload);
            if (insertError) {
              devError('Insert error:', insertError);
              throw insertError;
            }
          }

          updateOfflineQueueItem(profile.id, item.tempId, { logSynced: true });
        }

        if (!item.progressionSynced) {
          const { error: rpcError } = await supabase.rpc('process_hydration_event', {
            p_user_id: item.user_id,
            p_amount_ml: item.amount,
            p_temp_c: item.tempC || null,
            p_exercise_mins: item.exerciseMins || 0,
            p_is_fasting: item.isFasting || false
          });

          if (rpcError) {
            devError('RPC process_hydration_event error:', rpcError);
            throw rpcError;
          }

          updateOfflineQueueItem(profile.id, item.tempId, { progressionSynced: true });
        }

        removeOfflineQueueItem(profile.id, item.tempId);
        syncedCount += 1;
      }

      clearOfflineQueue(profile.id);
      setHasPendingCloudSync(false);
      if (syncedCount > 0) {
        toast.success(`Đã đồng bộ ${syncedCount} mục offline.`);
        await onWaterLogged?.();
        fetchAllWater();
      }
    } catch (err) {
      devError('syncOfflineLogs:', err);
      setHasPendingCloudSync(readOfflineQueue(profile.id).length > 0);
      toast.error('Không thể đồng bộ dữ liệu offline. Kiểm tra mạng.');
    }
  }, [profile?.id, onWaterLogged]);

  useEffect(() => {
    if (hasPendingCloudSync) syncOfflineLogs();
  }, [hasPendingCloudSync, syncOfflineLogs]);

  // ── Return ─────────────────────────────────────────────

  return {
    waterEntries,
    waterIntake,
    handleAddWater,
    handleDeleteEntry,
    handleEditEntry,
    hasPendingCloudSync,
    isSyncing,
    waterIntakeRef,
    waterEntriesRef,
    refetchWater: fetchAllWater,
    syncOfflineLogs,
  };
}

// ── Club sync (fire & forget) ──────────────────────────────

async function syncToClubs(userId: string, amountMl: number) {
  const { data: clubs } = await supabase
    .from('club_members')
    .select('club_id')
    .eq('user_id', userId);

  if (!clubs?.length) return;

  await Promise.allSettled(
    clubs.map(({ club_id }: { club_id: string }) =>
      Promise.all([
        supabase.rpc('increment_club_member_intake', {
          p_user_id: userId, p_club_id: club_id, p_amount_to_add: amountMl,
        }),
        supabase.from('club_activity').insert({
          club_id, user_id: userId,
          activity_type: 'drink',
          message: `da nap them ${amountMl}ml nuoc`,
        }),
      ]),
    ),
  );
}

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Activity, FlaskConical, Trophy, ArrowLeft, Box, Sparkles, Cpu } from 'lucide-react';
import { DeviceHero, ControlDeck, ArenaPaywall } from '../components/DeviceComponents';
import { DiagnosticsPanel, LedPatternStudio, AutomationCenter } from '../components/LabComponents';
import type { LedPattern, RuleTrigger, RuleAction, AutomationRule } from '../components/types';
import { AuraPulseEffect } from '../components/effects/AuraPulseEffect';

export default function BottleTab({
  profile,
  weatherData,
  isWeatherSynced,
  watchData,
  isWatchConnected,
  smartBottle,
  onBack,
}: {
  profile: Record<string, unknown>;
  weatherData: Record<string, unknown>;
  isWeatherSynced: boolean;
  watchData: Record<string, unknown>;
  isWatchConnected: boolean;
  smartBottle: Record<string, unknown>;
  onBack?: () => void;
}) {
  const [activeTab, setActiveTab] = useState<'lab' | 'arena'>('lab');
  const [labTab, setLabTab] = useState<'control' | 'diagnostics' | 'aura' | 'logic'>('control');

  // Local state for Demo/Lab controls
  const CAPACITY = 750;
  const [isSyncing, setIsSyncing] = useState(false);
  const [isConnected, setIsConnected] = useState(smartBottle?.isConnected || false);
  const [currentVolume, setCurrentVolume] = useState(smartBottle?.metrics?.currentVolume ?? CAPACITY);
  const [fillPercentage, setFillPercentage] = useState(
    smartBottle?.metrics?.currentVolume != null ? (smartBottle.metrics.currentVolume / CAPACITY) * 100 : 100
  );
  const [batteryLevel, setBatteryLevel] = useState(smartBottle?.metrics?.batteryLevel ?? 84);
  const [temperature, setTemperature] = useState(smartBottle?.metrics?.temperature ?? 24);
  const [latencyMs] = useState(24);
  const [signalStrength, setSignalStrength] = useState(smartBottle?.metrics?.signalStrength ?? 92);
  const [rawSensorSeries] = useState<number[]>(() => 
    Array.from({ length: 20 }, () => Math.random() * 100)
  );

  // LED & Automation state
  const [ledColor, setLedColor] = useState('#22d3ee');
  const [ledPattern, setLedPattern] = useState<LedPattern>('breathe');
  const [ruleTrigger, setRuleTrigger] = useState<RuleTrigger>('goal_time');
  const [ruleAction, setRuleAction] = useState<RuleAction>('red_strobe');
  const [ruleTime, setRuleTime] = useState('20:00');
  const [ruleThreshold, setRuleThreshold] = useState(50);
  const [rules, setRules] = useState<AutomationRule[]>([]);
  const [, setSyncLogs] = useState<Array<{id: number; action: string; timestamp: string}>>([]);

  // Sync from props (useSmartBottle returns metrics.currentVolume, not top-level)
  useEffect(() => {
    if (smartBottle) {
      setTimeout(() => {
        setIsConnected(smartBottle.isConnected);
        const vol = smartBottle.metrics?.currentVolume ?? currentVolume;
        setCurrentVolume(vol);
        setFillPercentage((vol / CAPACITY) * 100);
        if (smartBottle.metrics?.batteryLevel != null) setBatteryLevel(smartBottle.metrics.batteryLevel);
        if (smartBottle.metrics?.temperature != null) setTemperature(smartBottle.metrics.temperature);
        if (smartBottle.metrics?.signalStrength != null) setSignalStrength(smartBottle.metrics.signalStrength);
      }, 0);
    }
  }, [smartBottle]);

  // Handle drink simulation
  const handleDrink = (amount: number) => {
    if (!isConnected) return;
    setIsSyncing(true);
    setTimeout(() => {
      const newVol = Math.max(0, currentVolume - amount);
      setCurrentVolume(newVol);
      setFillPercentage((newVol / CAPACITY) * 100);
      setIsSyncing(false);
      setSyncLogs(prev => [...prev, { id: Date.now(), action: `Consumed ${amount}ml`, timestamp: new Date().toISOString() }]);
    }, 800);
  };

  const handleRefill = () => {
    if (!isConnected) return;
    setIsSyncing(true);
    setTimeout(() => {
      setCurrentVolume(CAPACITY);
      setFillPercentage(100);
      setIsSyncing(false);
      setSyncLogs(prev => [...prev, { id: Date.now(), action: 'Tank Refilled (100%)', timestamp: new Date().toISOString() }]);
    }, 1200);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white selection:bg-cyan-500/30 selection:text-cyan-200 font-sans relative overflow-hidden pb-32">
      {/* Global Background Aura */}
      <div className="fixed inset-0 pointer-events-none z-0">
        <AuraPulseEffect color={ledColor} size="xl" intensity={0.5} className="absolute -top-40 -left-40" />
        <AuraPulseEffect color={activeTab === 'arena' ? '#a855f7' : ledColor} size="xl" intensity={0.3} className="absolute -bottom-40 -right-40" />
        <div className="absolute inset-0 bg-slate-950/40 backdrop-blur-[100px]" />
      </div>

      {/* 1. Cyber Header */}
      <div className="sticky top-0 z-50 px-6 py-6 backdrop-blur-xl border-b border-white/5 bg-slate-950/20">
        <div className="flex items-center justify-between relative z-10">
          <div className="flex items-center gap-4">
            {onBack && (
              <button 
                onClick={onBack}
                className="w-10 h-10 rounded-full border border-white/10 bg-white/5 flex items-center justify-center active:scale-90 transition-transform"
              >
                <ArrowLeft size={20} className="text-white" />
              </button>
            )}
            <div>
              <p className="text-[10px] uppercase tracking-[0.4em] text-cyan-400 font-black">DigiBottle OS</p>
              <h1 className="text-xl font-black text-white tracking-tight mt-0.5">Control Center</h1>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="text-right hidden sm:block">
              <p className="text-[9px] uppercase tracking-widest text-slate-500 font-black">Identity</p>
              <p className="text-xs font-black text-white">{profile?.nickname || 'Cyber User'}</p>
            </div>
            <div className="w-10 h-10 rounded-xl border-2 border-cyan-400/30 overflow-hidden bg-slate-900 shadow-[0_0_15px_rgba(34,211,238,0.2)]">
              <img src={profile?.avatar_url || 'https://api.dicebear.com/7.x/avataaars/svg?seed=Cyber'} className="w-full h-full object-cover" alt="User" />
            </div>
          </div>
        </div>

        {/* 2. Main Tab Navigator */}
        <div className="flex gap-2 p-1.5 bg-slate-900/60 rounded-2xl border border-white/5 mt-6 relative z-10">
          <button 
            onClick={() => setActiveTab('lab')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl transition-all font-black text-xs uppercase tracking-widest ${activeTab === 'lab' ? 'bg-cyan-500 text-slate-950 shadow-lg' : 'text-slate-500 hover:text-white'}`}
          >
            <FlaskConical size={16} />
            <span>Phòng Lab</span>
          </button>
          <button 
            onClick={() => setActiveTab('arena')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl transition-all font-black text-xs uppercase tracking-widest ${activeTab === 'arena' ? 'bg-purple-500 text-white shadow-lg' : 'text-slate-500 hover:text-white'}`}
          >
            <Trophy size={16} />
            <span>Đấu trường</span>
          </button>
        </div>
      </div>

      {/* 3. Content Area */}
      <div className="relative z-10 px-6 pt-6">
        <AnimatePresence mode="wait">
          {activeTab === 'lab' ? (
            <motion.div 
              key="lab-view"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20 }}
              className="space-y-6"
            >
              {/* Primary Dashboard Hero */}
              <DeviceHero 
                isConnected={isConnected}
                isSyncing={isSyncing}
                fillPercentage={fillPercentage}
                currentVolume={currentVolume}
                batteryLevel={batteryLevel}
                signalStrength={signalStrength}
                latencyMs={latencyMs}
                temperature={temperature}
                onConnect={() => setIsConnected(true)}
                onDisconnect={() => setIsConnected(false)}
                equippedBottle={null}
              />

              {/* Lab Sub-navigation (Glass Bubbles) */}
              <div className="flex gap-3 overflow-x-auto pb-2 -mx-2 px-2 scrollbar-hide">
                {[
                  { id: 'control', label: 'Hệ thống', icon: Box },
                  { id: 'diagnostics', label: 'Cảm biến', icon: Activity },
                  { id: 'aura', label: 'Ánh sáng', icon: Sparkles },
                  { id: 'logic', label: 'Tự động', icon: Cpu }
                ].map(item => (
                  <button
                    key={item.id}
                    onClick={() => setLabTab(item.id as 'control' | 'diagnostics' | 'aura' | 'logic')}
                    className={`shrink-0 flex items-center gap-2 px-4 py-2.5 rounded-full border transition-all ${labTab === item.id ? 'bg-white text-slate-950 border-white font-black' : 'bg-slate-900/40 border-white/5 text-slate-400 font-bold hover:border-white/10'}`}
                  >
                    <item.icon size={14} />
                    <span className="text-xs uppercase tracking-tighter">{item.label}</span>
                  </button>
                ))}
              </div>

              {/* Lab Tab Content */}
              <div className="space-y-6">
                {labTab === 'control' && (
                  <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
                    <ControlDeck 
                      isConnected={isConnected}
                      isSyncing={isSyncing}
                      onDrink={handleDrink}
                      onRefill={handleRefill}
                      onForceSync={() => {}}
                    />
                  </motion.div>
                )}

                {labTab === 'diagnostics' && (
                  <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
                    <DiagnosticsPanel 
                      isConnected={isConnected}
                      batteryLevel={batteryLevel}
                      batteryHealth={98}
                      batteryCycleCount={42}
                      latencyMs={latencyMs}
                      rawSensorSeries={rawSensorSeries}
                      temperature={temperature}
                      signalStrength={signalStrength}
                      isOpen={true}
                      onToggle={() => {}}
                    />
                  </motion.div>
